INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('abercrombie-and-fitch-authentic-man-edt', 'Abercrombie & Fitch', 'Authentic Man', 'EDT', 'men', 'citrus', NULL, '{"top":["Grapefruit","Bergamot","Pink pepper"],"heart":["Ginger","Sage","Lavender"],"base":["Clearwood","Moss","Suede"]}', 'Abercrombie & Fitch Authentic Man: Эрэгтэйчүүдэд зориулсан цитрус үнэр (EDT). Эхний ноот: бэрсүүт жүрж, бергамот, ягаан чинжүү; зүрхний ноот: цагаан гаа, мэргэн өвс, лаванда; суурь ноот: клиэрвүүд, хөвд, илгэ.', 'Authentic Man by Abercrombie & Fitch is a Citrus Aromatic fragrance for men. This is a new fragrance. Authentic Man was launched in 2019. The nose behind this fragrance is Clement Gavarry.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/files/638536.jpg?v=1757969033', 'https://www.perfumecenter.com.mx/cdn/shop/files/085715166012.jpg?v=1706262693', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('abercrombie-and-fitch-authentic-moment-edt', 'Abercrombie & Fitch', 'Authentic Moment', 'EDT', 'men', 'woody', NULL, '{"top":["Cinnamon","Apple","Cypress","Bergamot","Neroli","Amberwood","Sandalwood","Musk"],"heart":[],"base":[]}', 'Abercrombie & Fitch Authentic Moment: Эрэгтэйчүүдэд зориулсан модлог үнэр (EDT). Эхний ноот: шанцай, алим, кипарис, бергамот, нероли, хув мод, зандан мод, заар.', 'Abercrombie & Fitch''s Authentic Moment Man perfume for men is the latest scent in the market. Launched in 2022, the fragrance was created by the expert nose of Yves Cassar. Its top notes are Cinnamon, Apple, Cypress, and Bergamot, complemented by Neroli as its middle note, and a base of Amberwood, Sandalwood, Musk, and Vanilla.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/40068b52-ecfe-4067-94a7-e15efb7ba4e1.jpg?v=1692396599', 'https://cdn.notinoimg.com/detail_main_hq/abercrombie-fitch-copy/85715169525_03-o/authentic-moment-men___240904.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('abercrombie-and-fitch-authentic-night-edp', 'Abercrombie & Fitch', 'Authentic Night', 'EDP', 'women', 'chypre', NULL, '{"top":["Blackcurrant","Apple","Pink pepper"],"heart":[],"base":[]}', 'Abercrombie & Fitch Authentic Night: Эмэгтэйчүүдэд зориулсан шипр үнэр (EDP). Эхний ноот: үхрийн нүд, алим, ягаан чинжүү.', 'Authentic Night Femme by Abercrombie & Fitch is a captivating Chypre Floral fragrance designed for women. Introduced in 2020, this new scent features an alluring blend of top notes including Black Currant, Apple, and Pink Pepper. The heart of the fragrance reveals floral notes of Tuberose, Jasmine Sambac, and Magnolia, while the base is crafted from rich Patchouli, Sandalwood, and Cedar.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/files/1292050.jpg?v=1741965493', 'https://cdn11.bigcommerce.com/s-2vt02okold/images/stencil/1280x1280/products/2973/2893/MAFAN__04028.1731099891.jpg?c=1', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('abercrombie-and-fitch-authentic-night-edt', 'Abercrombie & Fitch', 'Authentic Night', 'EDT', 'men', 'amber', NULL, '{"top":["Apple","Rhubarb","Lotus"],"heart":["Vanilla","Lavender","Clary sage"],"base":["Tonka bean","Leather","Oakmoss"]}', 'Abercrombie & Fitch Authentic Night: Эрэгтэйчүүдэд зориулсан хув үнэр (EDT). Эхний ноот: алим, гишүүнэ, бадамлянхуа; зүрхний ноот: ваниль, лаванда, мускат хашхираа; суурь ноот: тонка шош, арьс, царсны хөвд.', 'Authentic Night Homme by Abercrombie & Fitch is a Amber Fougere fragrance for men. This is a new fragrance. Authentic Night Homme was launched in 2020. Top notes are Apple, Rhubarb and Lotus; middle notes are Vanilla, Lavender and Clary Sage; base notes are Tonka Bean, Leather and Oakmoss.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/8a77d633-f859-4f17-94db-e5150d53451d_17afdba4-dde9-4351-8bc1-557a31108d7f.jpg?v=1683060481', 'https://cdn11.bigcommerce.com/s-2vt02okold/images/stencil/1280x1280/products/2660/5943/HAFAN__74697.1731099884.jpg?c=1', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('abercrombie-and-fitch-away-man-edt', 'Abercrombie & Fitch', 'Away Man', 'EDT', 'men', 'woody', NULL, '{"top":["Geranium","Ginger","Black pepper","Vetiver","Woods","Sandalwood"],"heart":[],"base":[]}', 'Abercrombie & Fitch Away Man: Эрэгтэйчүүдэд зориулсан модлог үнэр (EDT). Эхний ноот: герань, цагаан гаа, хар чинжүү, ветивер, модлог ноот, зандан мод.', 'The new fragrance for men, Away Man by Abercrombie & Fitch, was released in 2021 and features an invigorating Woody Aromatic scent. Atop this base are Violet, Pineapple and Grapefruit top notes, and the depths are filled with Geranium, Ginger, Pepper, Vetiver, Woody Notes and Sandalwood middle and base notes.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/5c937cf3-4f45-4725-b5d5-28e1667eea4f.jpg?v=1692396807', 'https://samawa.ae/cdn/shop/files/Abercrombie_FitchAwayMan_M_Edt100Ml_1200x1200.jpg?v=1692371876', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('abercrombie-and-fitch-fierce-cologne', 'Abercrombie & Fitch', 'Fierce', 'Cologne', 'men', 'woody', NULL, '{"top":["Petitgrain","Cardamom","Lemon","Orange","Fir","Marine notes"],"heart":["Jasmine","Rosemary","Rose","Lily-of-the-valley","Sage"],"base":["Vetiver","Musk","Oakmoss","Rosewood","Sandalwood"]}', 'Abercrombie & Fitch Fierce: Эрэгтэйчүүдэд зориулсан модлог үнэр (Cologne). Эхний ноот: петигрейн, кардамон, нимбэг, жүрж, жодоо, далайн ноот; зүрхний ноот: жасмин, розмарин, сарнай, хонхон цэцэг, мэргэн өвс; суурь ноот: ветивер, заар, царсны хөвд, сарнай мод, зандан мод.', 'Abercrombie & Fitch Fierce is a fresh, woody aromatic that became a modern classic. Bruno Jovanovic and Christophe Laudamiel created it in 2002. Fir, lemon, orange, cardamom, petitgrain and sea notes open fresh, rosemary, jasmine, rose and sage form the heart, and musk, vetiver, oakmoss and sandalwood give it a clean finish. A daytime favorite for spring and summer, the office and weekends. Fierce by Abercrombie & Fitch is a Woody Aromatic fragrance for men. Fierce was created by Christophe Laudamiel and Bruno Jovanovic. Top notes are petitgrain, cardamom, lemon, orange, fir and sea notes; middle notes are jasmine, rosemary, rose, lily-of-the-valley and sage; base notes are vetiver, musk, oakmoss, brazilian rosewood and sandalwood.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/7e539ad2-115b-45a0-999d-dcdca8fb9fa0.jpg?v=1683060564', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/a5edb5ed-f69b-4fdf-9539-c23db9c4ec1a_36beddbe-50cb-488c-937c-e573b159bc9e.jpg?v=1683060564', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('abercrombie-and-fitch-first-instinct-blue-edt', 'Abercrombie & Fitch', 'First Instinct Blue', 'EDT', 'men', 'woody', NULL, '{"top":[],"heart":["Lavender","Rosemary","Black pepper"],"base":["Amber","Tonka bean","Sandalwood"]}', 'Abercrombie & Fitch First Instinct Blue: Эрэгтэйчүүдэд зориулсан модлог үнэр (EDT). Зүрхний ноот: лаванда, розмарин, хар чинжүү; суурь ноот: хув, тонка шош, зандан мод.', 'The scent balances an energetic opening, a spicy development and an addictive trail. Frozen apple, combined with juicy bergamot and aromatic cardamom, gives an exciting first impression. A mix of pepper, rosemary and crisp lavender brightens up the heart while giving it an effortless flair. At the base, addictive amber, supported by rich Sandalwood and Tonka Beans, leaves a deeper trail of unexpected tones. It is Abercrombie’s fragrant interpretation of the moment of exhilaration when you feel the sky’s the limit. A fresh, one-of-a-kind Fougere scent for the adventurous man whose lives by his First Instinct. Head Notes: Frozen Apple, Cardamom, Bergamot Heart Notes: Crisp Lavender, Rosemary, Pepper Base Notes: Addictive Amber, Tonka Beans, Sandalwood', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/4d92e9f7-0531-488c-b15d-1d23b14b0feb.jpg?v=1683060641', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/4915e1bb-09ef-40ec-b771-001cca6d6256_0fe5a9a6-c487-407a-9c22-976066dc4b86.jpg?v=1683060641', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('abercrombie-and-fitch-first-instinct-edt', 'Abercrombie & Fitch', 'First Instinct', 'EDT', 'men', 'fresh', NULL, '{"top":["Gin","Tonic","Kiwano melon"],"heart":["Violet leaf","Sichuan pepper"],"base":["Cashmere wood","Amber","Musk"]}', 'Abercrombie & Fitch First Instinct: Эрэгтэйчүүдэд зориулсан сэрүүн үнэр (EDT). Эхний ноот: жин, тоник, кивано; зүрхний ноот: нил цэцгийн навч, сычуань чинжүү; суурь ноот: кашмир мод, хув, заар.', '''First Instinct'' is the first fragrance to be sold outside of the Abercrombie & Fitch boutiques. This addictive and irresistible fragrance is a fougere aromatic amber. Blended for the man who lives by his first instinct. This modern fragrance opens with electronic gin and Tonic combined with kiwano melon. In the heart, szechuan pepper ignites the spark to attraction while violet leaves bring depth and a citrus twist. The base is made up of suede musk and sleek warm amber, creating the perfect blend of fresh elements of fougere and oriental warmth.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/798ce6b3-3b32-423e-b150-744de0588b83.jpg?v=1683060717', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/fe87725d-d986-4a25-90c1-d91ca6187529_00fea57a-bb46-4a8f-b3e2-cc387efd50ec.jpg?v=1683060717', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('abercrombie-and-fitch-first-instinct-extreme-edp', 'Abercrombie & Fitch', 'First Instinct Extreme', 'EDP', 'men', 'fresh', NULL, '{"top":[],"heart":["Violet leaf","Saffron","Cardamom","Black pepper"],"base":["Leather","Cashmere wood","Amber","Coconut water"]}', 'Abercrombie & Fitch First Instinct Extreme: Эрэгтэйчүүдэд зориулсан сэрүүн үнэр (EDP). Зүрхний ноот: нил цэцгийн навч, гүргэм, кардамон, хар чинжүү; суурь ноот: арьс, кашмир мод, хув, кокосын ус.', 'An intriguing and charismatic, intensely masculine fragrance. The opening notes create an instant rush of invigorating pepper, followed by an unforgettable development of warm cardamom. The base notes leave an irresistible trail of sensual leather. It is Abercrombie’s fragrant take on the charismatic personality of a man who is naturally attractive. It''s a genuinely intriguing and addictive woody spicy oriental, blended for the man who is driven by his First Instinct. Head Notes: Invigorating Pepper, Mandarin Leaf, Star Fruit Heart Note: Violet Leaves, Saffron Powder Warm Cardamom, Spicy Pepper Base Notes: Sensual Leather, Cashmere Wood, Extreme Amber, Coconut Water', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/005fe677-6ace-4a1b-a9a6-d109342687f4.jpg?v=1683060793', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/8123c474-c6ab-4129-98fd-b1d6f65fb85c_59b80f04-3bc9-4602-ad5e-1dbe084b21ae.jpg?v=1683060793', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('abercrombie-and-fitch-first-instinct-together-edp', 'Abercrombie & Fitch', 'First Instinct Together', 'EDP', 'women', 'floral', NULL, '{"top":["Pineapple","Red currant","Lily-of-the-valley","Peony"],"heart":[],"base":[]}', 'Abercrombie & Fitch First Instinct Together: Эмэгтэйчүүдэд зориулсан цэцэгсийн үнэр (EDP). Эхний ноот: хан боргоцой, улаан үхрийн нүд, хонхон цэцэг, цээнэ цэцэг.', 'First Instinct Together Eau de Parfum For Her by Abercrombie & Fitch is a delightful Floral Fruity fragrance designed for women. Introduced in 2020, this new scent features top notes of Pineapple and Red Currant, followed by a heart of Lily-of-the-Valley and Peony. The fragrance concludes with a warm base of Musk, Amber, and Sandalwood.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/files/1292557.jpg?v=1742225321', 'https://cdn.shopify.com/s/files/1/0259/7733/products/abercrombie-first-instinct-together-women_1024x1024.png?v=1613535107', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('abercrombie-and-fitch-first-instinct-together-edt', 'Abercrombie & Fitch', 'First Instinct Together', 'EDT', 'men', 'woody', NULL, '{"top":["Green apple","Pineapple leaf","Grapefruit","Cardamom"],"heart":["Lavender","Orange blossom"],"base":["Musk","Sandalwood","Cedar"]}', 'Abercrombie & Fitch First Instinct Together: Эрэгтэйчүүдэд зориулсан модлог үнэр (EDT). Эхний ноот: ногоон алим, хан боргоцойн навч, бэрсүүт жүрж, кардамон; зүрхний ноот: лаванда, жүржийн цэцэг; суурь ноот: заар, зандан мод, хуш мод.', 'First Instinct Together Eau de Toilette For Him by Abercrombie & Fitch is a Woody Aromatic fragrance for men. This is a new fragrance. First Instinct Together Eau de Toilette For Him was launched in 2020. Top notes are Green Apple, Pineapple Leaf, Grapefruit and Cardamom; middle notes are Lavender and Orange Blossom; base notes are Musk, Sandalwood and Cedar.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/cb369437-e235-4ca4-b8e9-87d0ede11cf4_2ebcec8f-db2d-4982-b305-916f86817853.jpg?v=1683060866', 'https://fragrancelondon.com/cdn/shop/files/abercrombie-fitch-first-instinct-together-man-eau-de-toilette-spray-100ml-965753.webp?v=1747207277&width=1080', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('abercrombie-fitch-fierce-cologne', 'Abercrombie & Fitch', 'Fierce', 'Cologne', NULL, NULL, 2002, '{"top":["Fir Resin","Lemon","Cardamom","Orange","Petitgrain"],"heart":["Rosemary","Lily Of The Valley","Rose","Jasmine"],"base":["Oakmoss","Brazilian Rosewood","Musk","Vetiver"]}', NULL, NULL, 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/abercrombie-fitch-fierce-cologne_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/abercrombie-fitch-fierce-cologne_back.jpg', 'draft', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-ambra-edp', 'Acqua di Parma', 'Ambra', 'EDP', 'unisex', 'woody', NULL, '{"top":[],"heart":[],"base":[]}', 'Acqua di Parma Ambra: Unisex модлог үнэр (EDP).', 'The 2019 Ambra Eau de Parfum by Acqua di Parma is a Woody Aromatic fragrance meant to be worn by both men and women. At first, it carries with it a blend of Orange, Calabrian Bergamot and Petitgrain. Followed by a combination of Cedar, Cypriol Oil or Nagarmotha, Rose and Patchouli at the heart of the fragrance. Finally, the scent complements the aroma with Ambergris, Sandalwood, Musk, Vanilla and Labdanum at the base.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/6c6c85b6-d6b2-4bc3-94a1-b4eb5acb196c.jpg?v=1694453365', 'https://www.parfuem365.de/media/image/c3/99/f2/8028713810718_1.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-blu-mediterraneo-arancia-di-capri-edt', 'Acqua di Parma', 'Blu Mediterraneo Arancia Di Capri', 'EDT', 'unisex', 'citrus', 1999, '{"top":["Orange","Sicilian Mandarin","Bergamot","Lemon"],"heart":["Petitgrain","Cardamom"],"base":["Caramel","Musk"]}', 'Acqua di Parma Blu Mediterraneo Arancia Di Capri: Unisex цитрус үнэр (EDT).', 'This unisex perfume introduced in 1999 is full of fresh, aromatic and encouraging notes. Top notes bring us juicy freshness of orange, Sicilian mandarin, bergamot and luminous, bitter grapefruit. A heart is composed of petit grain and cardamom, while a base carries notes of caramel and musk.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-blu-mediterraneo-arancia-di-capri-edt_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-blu-mediterraneo-arancia-di-capri-edt_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-blu-mediterraneo-bergamotto-di-calabria-edt', 'Acqua di Parma', 'Blu Mediterraneo Bergamotto di Calabria', 'EDT', 'unisex', 'woody', 2010, '{"top":["Bergamot","Citron"],"heart":["Ginger","Cedar","Flowers"],"base":["Vetyver","Musk","Benzoin"]}', 'Acqua di Parma Blu Mediterraneo Bergamotto di Calabria: Unisex модлог үнэр (EDT).', 'The land of Calabria is strong and intense. Only here does authentic bergamot find its natural habitat. Its sparkling notes appear at the onset of this joyful and uplifting fragrance and are enhanced by the freshness of citron, red ginger, and cedarwood. At the base, an unprecedented combination of vetiver, benzoin, and musk emerges. Notes: Bergamot, Citron, Red Ginger, Cedarwood. Vetiver, Benzoin, and Musk. Style: Joyful. Uplifting. Unique.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-blu-mediterraneo-bergamotto-di-calabria-edt_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-blu-mediterraneo-bergamotto-di-calabria-edt_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-blu-mediterraneo-cedro-di-taormina-edt', 'Acqua di Parma', 'Blu Mediterraneo Cedro Di Taormina', 'EDT', 'unisex', 'woody', NULL, '{"top":[],"heart":[],"base":["Labdanum"]}', 'Acqua di Parma Blu Mediterraneo Cedro Di Taormina: Unisex модлог үнэр (EDT). Суурь ноот: лабданум.', 'The latest fragrance in the Blu Mediterraneo collection is inspired by Taormina—a spectacular landscape where the unique and lush nature of the Mediterranean vegetation blends with the impressive strength of volcanic rock formations. Fresh citrus essences and aromatic basil capture the landscape’s vibrant fragrance and sunlit radiance. In the heart of the fragrance, black pepper and lavender create a sparkling, spicy experience and blend perfectly with the elegant, intense base notes of cistus labdanum, vetiver, and Virginia cedarwood. Notes: Italian Citron, Black Pepper, Virginia Cedarwood, Elemi Resin, Vetiver, Guaiac. Style: Vibrant. Fresh. Sparkling.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/43370d36-e596-4553-8470-6e74c9ec35f7_7ab6a7b7-df8b-4b4b-a665-898607c637bc.jpg?v=1683061177', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/f298e579-3ffd-4ba4-ba92-e903c77dbd0e.jpg?v=1683061177', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-blu-mediterraneo-chinotto-di-liguria-edt', 'Acqua di Parma', 'Blu Mediterraneo Chinotto Di Liguria', 'EDT', 'unisex', 'chypre', NULL, '{"top":["Mandarin","Chinotto"],"heart":["Jasmine","Geranium","Cardamom","Rosemary"],"base":["Patchouli","Musk"]}', 'Acqua di Parma Blu Mediterraneo Chinotto Di Liguria: Unisex шипр үнэр (EDT). Эхний ноот: мандарин, чинотто; зүрхний ноот: жасмин, герань, кардамон, розмарин; суурь ноот: пачули, заар.', 'Chinotto di Liguria by Acqua di Parma is a Chypre Floral fragrance for women and men. Chinotto di Liguria was launched in 2018. Top notes are mandarin orange and chinotto; middle notes are jasmine, geranium, cardamom and rosemary; base notes are patchouli and musk.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/54f42fde-674e-4c71-8797-08245ce7dde0_b2a1f847-e515-41c6-a1f0-3ab8b03ccf8b.jpg?v=1683061254', 'https://www.boutiquetozzi.com/cdn/shop/products/ADP57036-150ML.2.H1.jpg?v=1584976889&width=1445', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-blu-mediterraneo-cipresso-di-toscana-cologne', 'Acqua di Parma', 'Blu Mediterraneo Cipresso di Toscana', 'Cologne', 'unisex', 'woody', NULL, '{"top":["Rosemary","Basil","Sage","Grapefruit","Petitgrain"],"heart":["Pine","Lavender","Coriander","Cardamom","Jasmine","Lily-of-the-valley"],"base":["Cypress","Pine","Vetiver","Cedar","Oakmoss","Patchouli"]}', 'Acqua di Parma Blu Mediterraneo Cipresso di Toscana: Unisex модлог үнэр (Cologne). Эхний ноот: розмарин, базилик, мэргэн өвс, бэрсүүт жүрж, петигрейн; зүрхний ноот: нарс, лаванда, кориандр, кардамон, жасмин, хонхон цэцэг; суурь ноот: кипарис, нарс, ветивер, хуш мод, царсны хөвд, пачули.', 'Acqua di Parma Blu Mediterraneo - Cipresso di Toscana by Acqua di Parma is a Woody Aromatic fragrance for women and men. Acqua di Parma Blu Mediterraneo - Cipresso di Toscana was launched in 2005. The nose behind this fragrance is Bertrand Duchaufour. Top notes are Rosemary, Basil, Sage, Grapefruit and Petitgrain; middle notes are Pine Tree, Lavender, Coriander, Cardamom, Jasmine and Lily-of-the-Valley; base notes are Cypress, Silver Pine, Vetiver, Cedar, Oakmoss and Patchouli.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/9f9d0b12-c4a8-47df-ab9c-fb75bd83150b.jpg?v=1683061335', NULL, 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-blu-mediterraneo-fico-di-amalfi-edt', 'Acqua di Parma', 'Blu Mediterraneo Fico Di Amalfi', 'EDT', 'unisex', 'woody', 2006, '{"top":["Grapefruit","Bergamot","Citron","Lemon"],"heart":["Fig Nectar","Jasmine","Pink Pepper"],"base":["Fig Tree","Cedar","Benzoin"]}', 'Acqua di Parma Blu Mediterraneo Fico Di Amalfi: Unisex модлог үнэр (EDT). Суурь ноот: инжир, хуш мод.', 'Acqua di Parma Fico di Amalfi is a sunny blend of citrus and fig. Launched in 2006, it opens with grapefruit, bergamot, citron and lemon. Fig nectar, jasmine and pink pepper form a juicy heart, and fig tree, cedar and benzoin give it a soft, woody finish. A summer favorite for everyday wear and the gym. The Amalfi Coast: it’s one of the most breathtaking places on Earth. This floral, woody, and citrusy fragrance calls to mind this breathtaking stretch of Mediterranean coastline with a strong, energizing effect. A unique combination of notes, including bergamot, lemon, grapefruit, and citron open the fragrance. Fig nectar, pink pepper, and jasmine petals are blended at the heart and base notes of fig wood, cedarwood, and benzoin follow. Notes: Bergamot, Lemon, Grapefruit, Citron, Fig Nectar, Pink Pepper, Jasmine Petals, Fig Wood, Cedarwood, and Benzoin. Style: Strong. Energizing. Unique.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-blu-mediterraneo-fico-di-amalfi-edt_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-blu-mediterraneo-fico-di-amalfi-edt_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-blu-mediterraneo-mandorlo-di-sicilia-edt', 'Acqua di Parma', 'Blu Mediterraneo Mandorlo di Sicilia', 'EDT', 'unisex', 'gourmand', 1999, '{"top":["Green Almond","Star Anise","Orange","Bergamot"],"heart":["White Peach","Ylang-Ylang","Jasmine"],"base":["Bourbon Vanilla","Tolu Balsam","White Musk","Cedar"]}', 'Acqua di Parma Blu Mediterraneo Mandorlo di Sicilia: Unisex гурман үнэр (EDT). Суурь ноот: хуш мод.', 'Sicily is a crossroads of art and culture, with the almond as part of the local tastes and traditions. Known in Italian as Mandorlo di Sicilia, the soothing appeal of Sicilian almond opens this delicious fragrance. Its sweet caress joins notes of star anise, bergamot, and orange. The fragrance’s heart blends green Mediterranean almond and ylang-ylang before base notes of cedarwood, vanilla, and white musk emerge. Notes: Sicilian Almond, Star Anise, Bergamot, Orange, Green Mediterranean Almond, Ylang-Ylang, Cedarwood, Vanilla, and White Musk. Style: Delicious. Sweet. Soothing.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-blu-mediterraneo-mandorlo-di-sicilia-edt_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-blu-mediterraneo-mandorlo-di-sicilia-edt_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-blu-mediterraneo-mirto-di-panarea-edt', 'Acqua di Parma', 'Blu Mediterraneo Mirto Di Panarea', 'EDT', 'unisex', 'woody', NULL, '{"top":[],"heart":[],"base":[]}', 'Acqua di Parma Blu Mediterraneo Mirto Di Panarea: Unisex модлог үнэр (EDT).', 'Panarea near Sicily is an an island suspended in time. The smallest and oldest of the Eolie islands, its essence is brought to life in this revitalizing fragrance. A scent characterized by the aromatic notes of myrtle and basil, it opens with lemon and bergamot. At the heart, a sea breeze accord melts with jasmine and rose. Its intense base includes lentisc and juniper with cedarwood and amber. Notes: Myrtle, Basil, Lemon, Bergamot, Sea Breeze Accord, Jasmine, Rose, Lentisc, Juniper, Cedarwood, and Amber. Style: Revitalizing. Intense. Aromatic.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/5a977119-beed-43bf-98ac-3bca1547bf4c_3f49a57a-809a-43fe-b204-43c651a76e0b.jpg?v=1683062930', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/000db419-229b-4d41-8e03-fc3352d80b32.jpg?v=1683062930', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-buongiorno-edp', 'Acqua di Parma', 'Buongiorno', 'EDP', NULL, NULL, NULL, '{"top":["Lemon","Mint","Rosemary","Basil","Petitgrain"],"heart":["Lavandin","Petitgrain"],"base":["Cedarwood","Amber","Musk"]}', NULL, NULL, 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-buongiorno-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-buongiorno-edp_back.jpg', 'draft', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-camelia-edp', 'Acqua di Parma', 'Camelia', 'EDP', 'unisex', 'floral', NULL, '{"top":["Bergamot","Mandarin","Pink pepper","Cardamom"],"heart":["Camellia","Jasmine","Clary sage"],"base":["Musk","Benzoin"]}', 'Acqua di Parma Camelia: Unisex цэцэгсийн үнэр (EDP). Эхний ноот: бергамот, мандарин, ягаан чинжүү, кардамон; зүрхний ноот: камелия, жасмин, мускат хашхираа; суурь ноот: заар, бензойн.', 'Camelia Eau de Parfum by Acqua di Parma is a Floral fragrance for women and men. Camelia Eau de Parfum was launched in 2019. Top notes are Calabrian bergamot, Yellow Mandarin, Pink Pepper and Cardamom; middle notes are Camelia, Jasmine Sambac and Clary Sage; base notes are Musk and Benzoin.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/d632fdce-8818-42c1-8767-94d796ba686b.jpg?v=1683061100', 'https://www.perfumenz.co.nz/cdn/shop/products/acqua-di-parma-camelia_1200x1200.png?v=1648427439', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-colonia-ambra-cologne', 'Acqua di Parma', 'Colonia Ambra', 'Cologne', 'men', 'amber', NULL, '{"top":[],"heart":[],"base":[]}', 'Acqua di Parma Colonia Ambra: Эрэгтэйчүүдэд зориулсан хув үнэр (Cologne).', 'Colonia Ambra by Acqua di Parma is a Amber fragrance for men. Colonia Ambra was launched in 2015.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/b0192740-8160-440c-8672-de83a42d1af1.jpg?v=1683061413', 'https://dscentsation.ng/cdn/shop/products/AcquaDiParmaColoniaAmbraEDC100mlPerfumeforMen.png?v=1645453031', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-colonia-assoluta-cologne', 'Acqua di Parma', 'Colonia Assoluta', 'Cologne', 'unisex', 'citrus', 2003, '{"top":["Bitter Orange","Bergamot","Lemon Verbena","Sweet Orange"],"heart":["Ylang-Ylang","Vetiver","Jasmine","Cedar","Pink Pepper","Cardamom","Paprika"],"base":["Oakmoss","Resins","White Musk","Patchouli"]}', 'Acqua di Parma Colonia Assoluta: Unisex цитрус үнэр (Cologne). Эхний ноот: гашуун жүрж; зүрхний ноот: иланг-иланг; суурь ноот: царсны хөвд, давирхай, заар, пачули.', 'Acqua di Parma Colonia Assoluta by Acqua di Parma is a Citrus Aromatic fragrance for women and men. Acqua di Parma Colonia Assoluta was launched in 2003. Acqua di Parma Colonia Assoluta was created by Bertrand Duchaufour and Jean-Claude Ellena. Top notes are Bitter Orange, Bergamot, Lemon Verbena and Sweet Orange; middle notes are Ylang-Ylang, Vetiver, Jasmine, Cedar, Cardamom, Pink Pepper and Paprika; base notes are Oakmoss, resins, White Musk and Patchouli.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-colonia-assoluta-cologne_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-colonia-assoluta-cologne_back.webp', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-colonia-c-l-u-b-cologne', 'Acqua di Parma', 'Colonia C.L.U.B.', 'Cologne', 'men', 'woody', NULL, '{"top":["Pink pepper","Lemon","Bergamot","Black pepper"],"heart":[],"base":[]}', 'Acqua di Parma Colonia C.L.U.B.: Эрэгтэйчүүдэд зориулсан модлог үнэр (Cologne). Эхний ноот: ягаан чинжүү, нимбэг, бергамот, хар чинжүү.', 'Colonia C.L.U.B. by Acqua di Parma is a Woody Spicy fragrance designed for men. Introduced as a fresh addition to the lineup in 2022, this scent opens with vibrant top notes of Pink Pepper, Lemon, Bergamot, and Black Pepper. Its heart is enriched with Shiso and Rosemary, while the base features the grounding notes of Cedar and Musk.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/files/d7c358cd-a350-4d73-abd1-db32fd57c894.jpg?v=1731423083', 'https://www.fraganciaslam.com.mx/storage/products/perf12362.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
