INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-colonia-cologne', 'Acqua di Parma', 'Colonia', 'Cologne', NULL, NULL, 1916, '{"top":["Lemon","Calabrian Bergamot","Orange"],"heart":["Lavender","Vervain","Bulgarian Rose","Rosemary"],"base":["Patchouli","Sandalwood","Vetiver"]}', NULL, NULL, NULL, 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-colonia-cologne_back.jpg', 'draft', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-colonia-ebano-concentree-cologne', 'Acqua di Parma', 'Colonia Ebano Concentree', 'Cologne', 'men', 'woody', NULL, '{"top":["Resins","Red pepper","Petitgrain"],"heart":["Ebony","Honey"],"base":["Vetiver"]}', 'Acqua di Parma Colonia Ebano Concentree: Эрэгтэйчүүдэд зориулсан модлог үнэр (Cologne). Эхний ноот: давирхай, улаан чинжүү, петигрейн; зүрхний ноот: хар мод, зөгийн бал; суурь ноот: ветивер.', 'Colonia Ebano by Acqua di Parma is a Woody fragrance for men. Colonia Ebano was launched in 2017. Top notes are resins, Red Pepper, Petitgrain and Bergamot; middle notes are Ebony and Honey; base notes are Vetiver and Patchouli.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/67fcf451-6a90-403f-80fb-07a2e01bdaac.jpg?v=1683061722', 'https://cdn.shopify.com/s/files/1/0259/7733/products/acqua-di-parma-colonia-ebano-180ml_grande.png?v=1569964338', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-colonia-essenza-cologne', 'Acqua di Parma', 'Colonia Essenza', 'Cologne', 'men', 'woody', NULL, '{"top":["Lemon","Neroli","Petitgrain","Bergamot","Grapefruit","Mandarin Orange","Orange"],"heart":["Rosemary","Clove","Jasmine","Lily Of The Valley","Rose"],"base":["White Musk","Vetiver","Amber","Patchouli"]}', 'Acqua di Parma Colonia Essenza: Эрэгтэйчүүдэд зориулсан модлог үнэр (Cologne).', 'Acqua di Parma Colonia Essenza is a richer, more refined take on the classic Italian cologne. Launched in 2015, it opens with mandarin, orange, petitgrain, bergamot and grapefruit. Neroli, sage, jasmine, rose and rosemary form an elegant heart, and clove, moss, patchouli, vetiver and amber give it depth. A polished daytime scent for spring and summer and a natural fit for the office. The newest Eau de Cologne from Acqua di Parma is hand crafted in the same tradition as the original and iconic Colonia, representing the essence of Italian luxury and style. Colonia Essenza is a woodsy citrus fragrance, using only the finest and purest essences for the formula. Notes: Bergamot, Lemon, Mandarin, Orange, Grapefruit, Petitgrain, Neroli, Rosemary, Clove, Lilly of the Valley, Rose Accord, Jasmine Accord, Patchouli, Vetiver, White Musk, Amber. Style: Refined. Elegant. Stylish.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-colonia-essenza-cologne_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-colonia-essenza-cologne_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-colonia-futura-cologne', 'Acqua di Parma', 'Colonia Futura', 'Cologne', 'unisex', 'citrus', NULL, '{"top":["Lemon","Bergamot","Grapefruit","Pink pepper"],"heart":["Lavender","Sage"],"base":["Vetiver"]}', 'Acqua di Parma Colonia Futura: Unisex цитрус үнэр (Cologne). Эхний ноот: нимбэг, бергамот, бэрсүүт жүрж, ягаан чинжүү; зүрхний ноот: лаванда, мэргэн өвс; суурь ноот: ветивер.', 'Colonia Futura by Acqua di Parma is a Citrus Aromatic fragrance for women and men. This is a new fragrance. Colonia Futura was launched in 2020. Top notes are Lemon, Bergamot, Grapefruit and Pink Pepper; middle notes are Lavender and Sage; base note is Vetiver.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/d000ab2c-f625-49b2-97a1-b33ca5ae262d.jpg?v=1683061875', 'https://cdn.fragrancenet.com/images/photos/1600x1600/377754.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-colonia-il-profumo-edp', 'Acqua di Parma', 'Colonia Il Profumo', 'EDP', 'unisex', 'aromatic', NULL, '{"top":["Orange","Bergamot","Lemon","Petitgrain","Pineapple","Verbena","Neroli","Lavender"],"heart":[],"base":["Moss","Vetiver","Cedar","Patchouli","Leather","Sandalwood"]}', 'Acqua di Parma Colonia Il Profumo: Unisex өвслөг үнэр (EDP). Эхний ноот: жүрж, бергамот, нимбэг, петигрейн, хан боргоцой, вербена, нероли, лаванда; суурь ноот: хөвд, ветивер, хуш мод, пачули, арьс, зандан мод.', 'Colonia Il Profumo by Acqua di Parma is an Aromatic Fruity fragrance designed for both women and men. This fresh scent was introduced in 2025. The top notes feature vibrant Orange, Bergamot, Lemon, Petitgrain, and Pineapple, while the heart of the fragrance blooms with Verbena, Neroli, Lavender, Ylang-Ylang, and Rose. The base notes create a rich foundation with Moss, Vetiver, Cedar, Patchouli, Leather, and Sandalwood.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/files/1300937.jpg?v=1746802080', 'https://www.perfumenz.co.nz/cdn/shop/files/acqua-di-parma-colonia-II-profumo_1400x1400.png?v=1765503755', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-colonia-intensa-cologne', 'Acqua di Parma', 'Colonia Intensa', 'Cologne', 'men', 'woody', NULL, '{"top":["Citrus notes","Bergamot","Cardamom","Ginger"],"heart":["Neroli","Cedar","Myrrh","Guaiac wood"],"base":["Leather","Benzoin","Musk","Patchouli"]}', 'Acqua di Parma Colonia Intensa: Эрэгтэйчүүдэд зориулсан модлог үнэр (Cologne). Эхний ноот: цитрусын ноот, бергамот, кардамон, цагаан гаа; зүрхний ноот: нероли, хуш мод, мирра, гваяк мод; суурь ноот: арьс, бензойн, заар, пачули.', 'Colonia Intensa by Acqua di Parma is a Woody fragrance for men. Colonia Intensa was launched in 2007. Colonia Intensa was created by Alberto Morillas and Francois Demachy. Top notes are Citruses, Bergamot, Cardamom, Ginger and Sicilian Lemon; Middle notes are Neroli, Cedar, Myrhh, Guaiac Wood and Artemisia; Base notes are Leather, Benzoin, Musk and Patchouli.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/dac65d26-eeda-4cf8-b868-323c87998495_ad7315aa-d9a3-4b2f-90e9-4c3f4ca12754.jpg?v=1683061952', 'https://www.perfumenz.co.nz/cdn/shop/products/acqua-di-parma-colonia-intensa-100ml_1200x1200.png?v=1573005939', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-colonia-leather-cologne', 'Acqua di Parma', 'Colonia Leather', 'Cologne', 'men', 'woody', NULL, '{"top":[],"heart":[],"base":[]}', 'Acqua di Parma Colonia Leather: Эрэгтэйчүүдэд зориулсан модлог үнэр (Cologne).', 'Acqua Di Parma presents an original creation born from the unconventional pairing of fresh citrus notes from the iconic Colonia fragrance and the rich and sensual caress of aromatic leather. Colonia Leather Eau de Cologne Concentrée recalls the artistic luxury and traditions of handcrafted leather and accessories. Notes: Sicilian Lemon, Italian Orange, Raspberry, Honeysuckle, Petit Grain, Rose, Leather, Cedarwood, Birchwood, Gaiac Wood, Labdaum. Style: Stylish. Elegant. Masculine.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/7f499bf1-7809-43a6-9f9b-3906be63a103_0ae6493f-a203-4d56-8278-882729fd9e01.jpg?v=1683062031', 'https://cdn.shopify.com/s/files/1/0259/7733/products/acqua-di-parma-colonia-leather_grande.png?v=1569965025', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-colonia-mirra-cologne', 'Acqua di Parma', 'Colonia Mirra', 'Cologne', 'men', 'amber', NULL, '{"top":["Orange blossom","Citrus notes"],"heart":["Myrrh","Nutmeg"],"base":["Amber","Patchouli"]}', 'Acqua di Parma Colonia Mirra: Эрэгтэйчүүдэд зориулсан хув үнэр (Cologne). Эхний ноот: жүржийн цэцэг, цитрусын ноот; зүрхний ноот: мирра, задийн самар; суурь ноот: хув, пачули.', 'Colonia Mirra by Acqua di Parma is a Amber Woody fragrance for men. Colonia Mirra was launched in 2017. Top notes are Orange Blossom and Citruses; middle notes are Myrhh and Nutmeg; base notes are Amber and Patchouli.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/2b9018dc-043f-4cf9-b665-1b8301c66794.jpg?v=1683062101', 'https://img.fragrancex.com/images/products/sku/large/adp34tw.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-colonia-oud-cologne', 'Acqua di Parma', 'Colonia Oud', 'Cologne', 'men', 'amber', 2012, '{"top":["Calabrian Bergamot","Italian Orange"],"heart":["Agarwood (Oud)","Amyris","Coriander"],"base":["Leather","Atlas Cedar","Sandalwood","Musk","Indonesian Patchouli Leaf"]}', 'Acqua di Parma Colonia Oud: Эрэгтэйчүүдэд зориулсан хув үнэр (Cologne). Эхний ноот: бергамот, жүрж, агар мод, амирис, кориандр.', 'Colonia Oud, crafted by Acqua di Parma, is an enticing Amber Woody fragrance designed for men. Introduced in 2012, this captivating scent was created by perfumer Francois Demachy. It opens with fresh top notes of Calabrian bergamot and Italian orange, leading into a heart of agarwood (oud), amyris, and coriander. The fragrance concludes with a rich base of leather, Atlas cedar, sandalwood, musk, and Indonesian patchouli leaf. Hailing from Southeast Asia, Oud is rare and widely sought after. It is said to cost more than its weight in gold. A new interpretation of Colonia Intensa, Colonia Oud combines the unique freshness of Colonia Intensa with one of the world’s most cherished ingredients, Oud, for an unforgettable fragrance that is both fresh and richly aromatic. A touch of masculine elegance. The traditional Acqua di Parma Colonia Intensa bottle shape is distinguished with a deep matte brown finish on the glass and cap. Colonia Intensa Oud is presented in a hand crafted box lined with luxurious brown satin. Notes: Bergamot from Calabria, Italian Orange, Haitian Amyris Oil, Russian Coriander, Agarwood Oil, Moroccan Cedarwood, Indonesian Patchouli Oil, Leather Accord, Sandalwood Accord, Musk. Style: Luxurious. Fresh. Masculine.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-colonia-oud-cologne_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-colonia-oud-cologne_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-colonia-pura-cologne', 'Acqua di Parma', 'Colonia Pura', 'Cologne', 'unisex', 'citrus', 2017, '{"top":["Ozonic Notes","Bergamot","Orange","Petitgrain"],"heart":["Narcissus","Jasmine Sambac","Coriander"],"base":["White Musk","Cedar","Patchouli"]}', 'Acqua di Parma Colonia Pura: Unisex цитрус үнэр (Cologne). Эхний ноот: далайн ноот, бергамот, жүрж, петигрейн; зүрхний ноот: нарцисс, жасмин, кориандр; суурь ноот: заар, хуш мод, пачули.', 'Acqua di Parma Colonia Pura is a Unisex fragrance, The fragrance launched in 2017, The nose behind this fragrance is Francois Demachy,', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-colonia-pura-cologne_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-colonia-pura-cologne_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-colonia-quercia-cologne', 'Acqua di Parma', 'Colonia Quercia', 'Cologne', 'men', 'citrus', NULL, '{"top":["Bergamot","Lemon","Petitgrain","Pink pepper"],"heart":[],"base":[]}', 'Acqua di Parma Colonia Quercia: Эрэгтэйчүүдэд зориулсан цитрус үнэр (Cologne). Эхний ноот: бергамот, нимбэг, петигрейн, ягаан чинжүү.', 'Colonia Quercia, crafted by Acqua di Parma, is an amber-spicy fragrance designed for men. Introduced in 2016, this scent opens with lively top notes of Bergamot, Lemon, Petitgrain, and Pink Pepper. The heart reveals a captivating blend of Geranium, Cedar, and Cardamom, while the base features deep, earthy notes of Oakmoss, Tonka Bean, and Patchouli.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/files/666480.jpg?v=1745437407', 'https://www.perfumenz.co.nz/cdn/shop/products/acqua-di-parma-colonia-quercia-180ml_1024x1024.png?v=1569966495', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-colonia-quercia-concentree-edp', 'Acqua di Parma', 'Colonia Quercia Concentree', 'EDP', 'unisex', 'woody', NULL, '{"top":["Lemon","Pink pepper","Bergamot","Petitgrain"],"heart":["Cardamom","Cedar","Geranium"],"base":["Moss","Tonka bean","Patchouli"]}', 'Acqua di Parma Colonia Quercia Concentree: Unisex модлог үнэр (EDP). Эхний ноот: нимбэг, ягаан чинжүү, бергамот, петигрейн; зүрхний ноот: кардамон, хуш мод, герань; суурь ноот: хөвд, тонка шош, пачули.', 'Quercia Eau de Parfum by Acqua di Parma is a Woody Aromatic fragrance for women and men. Quercia Eau de Parfum was launched in 2019. Top notes are Lemon, Pink Pepper, Calabrian bergamot and Petitgrain; middle notes are Cardamom, Cedar and Geranium; base notes are Moss, Tonka Bean and Patchouli.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/3d75d7d8-05f4-4fac-be33-6491d8fcc579.jpg?v=1683063439', 'https://luxplus.imgix.net/content/product/image/130668-58097-1708950383.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-gelsomino-a-freddo-edp', 'Acqua di Parma', 'Gelsomino A Freddo', 'EDP', 'unisex', 'woody', NULL, '{"top":["Pink pepper","Artemisia","Lemon"],"heart":[],"base":["Patchouli","Guaiac wood","Nagarmotha"]}', 'Acqua di Parma Gelsomino A Freddo: Unisex модлог үнэр (EDP). Эхний ноот: ягаан чинжүү, шарилж, нимбэг; суурь ноот: пачули, гваяк мод, нагармота.', 'Gelsomino A Freddo, crafted by Acqua di Parma, is a unisex fragrance that debuted in 2025. This captivating scent opens with vibrant top notes of Pink Pepper, Artemisia, and Lemon. At the heart, you''ll find a delightful blend of Jasmine, Iris, and Black Tea, while the foundation comprises rich base notes of Patchouli, Guaiac Wood, and Nagarmotha.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/files/1354801.jpg?v=1757958149', 'https://hrd-live.cdn.scayle.cloud/images/861a77977e77fe2a486005108e5290c6.jpg?bg=ffffff&brightness=1&height=1230&quality=75&width=922', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-gelsomino-nobile-edp', 'Acqua di Parma', 'Gelsomino Nobile', 'EDP', 'women', 'floral', 2011, '{"top":["Mandarin Orange","Pink Pepper"],"heart":["Jasmine","Tuberose","Orange Blossom"],"base":["Musk","Cedar"]}', 'Acqua di Parma Gelsomino Nobile: Эмэгтэйчүүдэд зориулсан цэцэгсийн үнэр (EDP). Эхний ноот: мандарин, ягаан чинжүү, жасмин, тубероз, жүржийн цэцэг; зүрхний ноот: жасмин, тубероз, жүржийн цэцэг; суурь ноот: заар, хуш мод.', 'Acqua di Parma Gelsomino Nobile is a Floral Woody Musk fragrance designed for women, introduced in 2011. The scent was crafted by renowned perfumers Michel Almairac and Francois Demachy. The fragrance opens with vibrant top notes of Mandarin Orange and Pink Pepper, leading into a heart of exquisite Jasmine, Tuberose, and Orange Blossom. The composition is anchored by a warm base of Musk and Cedar. Acqua di Parma Gelsomino Nobile by Acqua di Parma is a Floral Woody Musk fragrance for women. Acqua di Parma Gelsomino Nobile was launched in 2011. Acqua di Parma Gelsomino Nobile was created by Michel Almairac and Francois Demachy. Top notes are Mandarin Orange and Pink Pepper; middle notes are Jasmine, Tuberose and Orange Blossom; base notes are Musk and Cedar.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-gelsomino-nobile-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-gelsomino-nobile-edp_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-iris-nobile-edp', 'Acqua di Parma', 'Iris Nobile', 'EDP', 'women', 'floral', 2006, '{"top":["Iris","Star Anise","Bergamot","Mandarin Orange","Orange"],"heart":["Tuberose","Orange Blossom","Mimosa","Ylang-Ylang","Hibiscus","Cedar"],"base":["Vanilla","Amber"]}', 'Acqua di Parma Iris Nobile: Эмэгтэйчүүдэд зориулсан цэцэгсийн үнэр (EDP). Эхний ноот: цахилдаг, одон анис; зүрхний ноот: тубероз, жүрж; суурь ноот: ваниль.', 'Acqua di Parma Iris Nobile by Acqua di Parma is a Floral Woody Musk fragrance for women. Acqua di Parma Iris Nobile was launched in 2006. Acqua di Parma Iris Nobile was created by Francoise Caron and Francis Kurkdjian. Top notes are iris, Star Anise, Bergamot, Orange and Mandarin Orange; middle notes are Tuberose, Orange Blossom, Mimosa, Ylang-Ylang, Hibiscus and Cedar; base notes are Vanilla and Amber.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-iris-nobile-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-iris-nobile-edp_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-leather-edp', 'Acqua di Parma', 'Leather', 'EDP', 'unisex', 'woody', NULL, '{"top":["Raspberry","Orange","Lemon"],"heart":["Thyme","Honeysuckle","Petitgrain"],"base":["Leather","Cedar","Guaiac wood"]}', 'Acqua di Parma Leather: Unisex модлог үнэр (EDP). Эхний ноот: бөөрөлзгөнө, жүрж, нимбэг; зүрхний ноот: ганга, далан хальс, петигрейн; суурь ноот: арьс, хуш мод, гваяк мод.', 'Leather Eau de Parfum by Acqua di Parma is a unisex fragrance that embodies the essence of leather. Introduced in 2019, this scent opens with vibrant top notes of Raspberry, Brazilian Orange, and Sicilian Lemon. The heart features a floral blend of Rose, Red Thyme, Honeysuckle, and Petitgrain, while the base is enriched with warm notes of Leather, Guaiac Wood, and Cedar. Leather Eau de Parfum by Acqua di Parma is a Leather fragrance for women and men. This is a new fragrance. Leather Eau de Parfum was launched in 2019. Top notes are brazilian orange, sicilian lemon and raspberry; middle notes are red thyme, honeysuckle, petitgrain and rose; base notes are leather, cedar and guaiac wood.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/files/546202.jpg?v=1745438045', 'https://cdn2.jomashop.com/media/catalog/product/cache/fde19e4197824625333be074956e7640/a/c/acqua-di-parma-leather-eau-de-parfum-spray-34-oz-100-ml-8028713810619_3.jpg?height=546&width=546', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-lily-of-the-valley-edp', 'Acqua di Parma', 'Lily Of The Valley', 'EDP', 'unisex', 'floral', NULL, '{"top":["Blackcurrant","Grapefruit","Bergamot"],"heart":["Lily-of-the-valley","Jasmine","Geranium","Magnolia"],"base":["Cedar","Musk"]}', 'Acqua di Parma Lily Of The Valley: Unisex цэцэгсийн үнэр (EDP). Эхний ноот: үхрийн нүд, бэрсүүт жүрж, бергамот; зүрхний ноот: хонхон цэцэг, жасмин, герань, магнолия; суурь ноот: хуш мод, заар.', 'Lily of the Valley by Acqua di Parma is a Floral fragrance for women and men. This is a new fragrance. Lily of the Valley was launched in 2021. Top notes are Black Currant, Grapefruit and Bergamot; middle notes are Lily-of-the-Valley, Jasmine, Geranium and Magnolia; base notes are Cedar and Musk.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/d0247180-371a-4fcd-8e85-c88598ff27ef_a63b3ca6-7dc8-4b0f-a5f7-70e95bb7fc26.jpg?v=1683062700', 'https://www.perfumenz.co.nz/cdn/shop/files/acqua-di-parma-lily-of-the-valley_1200x1200.png?v=1704842036', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-magnolia-nobile-edp', 'Acqua di Parma', 'Magnolia Nobile', 'EDP', 'women', 'floral', 2009, '{"top":["Citron","Lemon","Bergamot"],"heart":["Magnolia","Jasmine","Tuberose","Rose"],"base":["Vetiver","Sandalwood","Vanilla","Patchouli"]}', 'Acqua di Parma Magnolia Nobile: Эмэгтэйчүүдэд зориулсан цэцэгсийн үнэр (EDP). Эхний ноот: цитрон, нимбэг, бергамот; зүрхний ноот: магнолия, жасмин, сарнай, тубероз; суурь ноот: ветивер.', 'Acqua di Parma Magnolia Nobile by Acqua di Parma is a Floral Fruity fragrance for women. Acqua di Parma Magnolia Nobile was launched in 2009. The nose behind this fragrance is Antoine Maisondieu. Top notes are Citron, Lemon and Bergamot; middle notes are Magnolia, Jasmine, Rose and Tuberose; base notes are Vetiver, Sandalwood, Patchouli and Vanilla.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-magnolia-nobile-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-magnolia-nobile-edp_back.png', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-mirto-di-panarea-la-riserva-edp', 'Acqua di Parma', 'Mirto di Panarea La Riserva', 'EDP', 'unisex', 'aromatic', NULL, '{"top":["Citron","Juniper","Sage","Lavender","Myrtle","Myrrh"],"heart":[],"base":[]}', 'Acqua di Parma Mirto di Panarea La Riserva: Unisex өвслөг үнэр (EDP). Эхний ноот: цитрон, арц, мэргэн өвс, лаванда, мирт, мирра.', 'Mirto di Panarea La Riserva by Acqua di Parma is a fresh and citrusy aromatic fragrance suitable for both women and men. This innovative scent was introduced in 2025. The fragrance opens with top notes of Citron, Juniper Berries, and Sage, leading into a heart of Lavender, Myrtle, and Myrrh. The base is enriched with Patchouli, Labdanum, and Mastic (Lentisque).', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/files/1377265.jpg?v=1782754354', 'https://www.perfumenz.co.nz/cdn/shop/files/acqua-di-parma-mirto-di-panarea-la-riserva_2830f5fb-280f-475b-a606-ece965654316_1652x1652.png?v=1768946637', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-note-di-colonia-i-cologne', 'Acqua di Parma', 'Note di Colonia I', 'Cologne', 'unisex', 'chypre', NULL, '{"top":["Bergamot","Neroli"],"heart":["Violet","Rose","Lavender"],"base":["Patchouli","Cedar"]}', 'Acqua di Parma Note di Colonia I: Unisex шипр үнэр (Cologne). Эхний ноот: бергамот, нероли; зүрхний ноот: нил цэцэг, сарнай, лаванда; суурь ноот: пачули, хуш мод.', 'Note di Colonia I by Acqua di Parma is a Chypre Floral fragrance for women and men. Note di Colonia I was launched in 2016. Top notes are Bergamot and Neroli; middle notes are Violet, Damask Rose and Lavender; base notes are Patchouli and Cedar.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/9e5322f8-af85-4041-a7ba-e65bc91e1c77.jpg?v=1683063004', 'https://hrd-live.cdn.scayle.cloud/images/f0a0584fbbb3bfbe32554fbf3f273228.jpg?bg=ffffff&brightness=1&height=1230&quality=75&width=922', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-note-di-colonia-iii-cologne', 'Acqua di Parma', 'Note di Colonia III', 'Cologne', 'unisex', 'amber', NULL, '{"top":["Mandarin","Ginger"],"heart":["Incense","Vetiver","Jasmine"],"base":["Myrrh","Labdanum","Tonka bean"]}', 'Acqua di Parma Note di Colonia III: Unisex хув үнэр (Cologne). Эхний ноот: мандарин, цагаан гаа; зүрхний ноот: хүж, ветивер, жасмин; суурь ноот: мирра, лабданум, тонка шош.', 'Note di Colonia III by Acqua di Parma is a Amber fragrance for women and men. Note di Colonia III was launched in 2016. Top notes are Mandarin Orange and Ginger; middle notes are Olibanum, Vetiver and Jasmine; base notes are Myrhh, Labdanum and Tonka Bean.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/8e47ec2a-cdd6-43f9-9e3e-6bad3a211680.jpg?v=1683063048', 'https://hrd-live.cdn.scayle.cloud/images/03afd79a11c723fbe5bfa48888ffe8b7.jpg?bg=ffffff&brightness=1&height=1230&quality=75&width=922', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-note-di-colonia-iv-cologne', 'Acqua di Parma', 'Note di Colonia IV', 'Cologne', 'unisex', 'amber', NULL, '{"top":["Mandarin","Bergamot"],"heart":["Orange blossom","Rose"],"base":["Opoponax","Labdanum","Patchouli"]}', 'Acqua di Parma Note di Colonia IV: Unisex хув үнэр (Cologne). Эхний ноот: мандарин, бергамот; зүрхний ноот: жүржийн цэцэг, сарнай; суурь ноот: опопонакс, лабданум, пачули.', 'Note di Colonia IV by Acqua di Parma is a Amber Floral fragrance for women and men. Note di Colonia IV was launched in 2017. Top notes are Mandarin Orange and Bergamot; middle notes are Orange Blossom and Turkish Rose; base notes are Opoponax, Labdanum and Patchouli.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/8bbcff2c-8814-46d2-93e4-c0140e6cb364.jpg?v=1683063093', 'https://cdn2.jomashop.com/media/catalog/product/cache/fde19e4197824625333be074956e7640/a/c/acqua-di-parma-unisex-note-di-colonia-iv-edc-spray-5-oz-fragrances-8028713290053_2.jpg?height=546&width=546', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-osmanthus-edp', 'Acqua di Parma', 'Osmanthus', 'EDP', 'unisex', 'floral', NULL, '{"top":["Neroli","Mandarin"],"heart":["Ambrette","Peony","Pink pepper"],"base":["Osmanthus","Patchouli"]}', 'Acqua di Parma Osmanthus: Unisex цэцэгсийн үнэр (EDP). Эхний ноот: нероли, мандарин; зүрхний ноот: амбретт, цээнэ цэцэг, ягаан чинжүү; суурь ноот: османтус, пачули.', 'Osmanthus Eau de Parfum by Acqua di Parma is a Floral fragrance for women and men. This is a new fragrance. Osmanthus Eau de Parfum was launched in 2019. Top notes are Neroli and Green Mandarin; middle notes are Ambrette (Musk Mallow), Peony and Pink Pepper; base notes are Osmanthus and Patchouli.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/a22795b4-dd40-439e-8341-cd17d5c07b3f_3738d461-2773-4550-b64e-4501f8e6fe7b.jpg?v=1683063139', 'https://hrd-live.cdn.scayle.cloud/images/262750406600a1492a228cf8c0a6b170.jpg?quality=75', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-oud-and-spice-edp', 'Acqua di Parma', 'Oud & Spice', 'EDP', 'men', 'woody', NULL, '{"top":["Raspberry","Rose","Bergamot"],"heart":["Clove","Pink pepper","Cinnamon"],"base":["Oud","Labdanum","Patchouli"]}', 'Acqua di Parma Oud & Spice: Эрэгтэйчүүдэд зориулсан модлог үнэр (EDP). Эхний ноот: бөөрөлзгөнө, сарнай, бергамот; зүрхний ноот: гвоздик, ягаан чинжүү, шанцай; суурь ноот: агар мод, лабданум, пачули.', 'Oud & Spice by Acqua di Parma is a Woody Spicy fragrance for men. This is a new fragrance. Oud & Spice was launched in 2021. Top notes are Raspberry, Rose and Bergamot; middle notes are Cloves, Pink Pepper and Cinnamon; base notes are Agarwood (Oud), Labdanum and Patchouli.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/f9089778-f97f-49cb-9907-e0bf1a9d7420.jpg?v=1683063288', 'https://www.perfumenz.co.nz/cdn/shop/products/acqua-di-parma-oud-spice_1024x1024.jpg?v=1660279917', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-oud-edp', 'Acqua di Parma', 'Oud', 'EDP', NULL, NULL, 2019, '{"top":["Orange","Calabrian Bergamot"],"heart":["Agarwood (Oud)","Amyris","Coriander"],"base":["Leather","Sandalwood","Musk","Cedar","Patchouli"]}', NULL, NULL, NULL, 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-oud-edp_back.png', 'draft', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-peonia-nobile-edp', 'Acqua di Parma', 'Peonia Nobile', 'EDP', 'women', 'floral', NULL, '{"top":[],"heart":[],"base":[]}', 'Acqua di Parma Peonia Nobile: Эмэгтэйчүүдэд зориулсан цэцэгсийн үнэр (EDP).', 'Peonia Nobile by Acqua di Parma is a Floral fragrance for women. Peonia Nobile was launched in 2016.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/7e1c87f3-8769-4054-b050-a4f4b8752ea6.jpg?v=1683063363', 'https://www.perfumenz.co.nz/cdn/shop/products/acqua-di-parma-peonia-nobile_1200x1200.png?v=1573420108', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-rosa-nobile-edp', 'Acqua di Parma', 'Rosa Nobile', 'EDP', 'women', 'floral', 2014, '{"top":["Mandarin Orange","Pepper","Bergamot"],"heart":["Rose","Peony","Violet","Lily-Of-The-Valley"],"base":["Musk","Cedar","Ambergris"]}', 'Acqua di Parma Rosa Nobile: Эмэгтэйчүүдэд зориулсан цэцэгсийн үнэр (EDP). Эхний ноот: мандарин, бергамот, хар чинжүү; зүрхний ноот: сарнай, цээнэ цэцэг, нил цэцэг, хонхон цэцэг; суурь ноот: заар, хуш мод, амбра.', 'Rosa Nobile by Acqua di Parma is a Floral Woody Musk fragrance for women. Rosa Nobile was launched in 2014. The nose behind this fragrance is Francois Demachy. Top notes are Mandarin Orange, Bergamot and Pepper; middle notes are Rose, Peony, Violet and Lily-of-the-Valley; base notes are Musk, Cedar and Ambergris.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-rosa-nobile-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/acqua-di-parma-rosa-nobile-edp_back.png', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-sakura-edp', 'Acqua di Parma', 'Sakura', 'EDP', 'unisex', 'citrus', NULL, '{"top":["Bergamot","Mandarin","Pink pepper"],"heart":[],"base":[]}', 'Acqua di Parma Sakura: Unisex цитрус үнэр (EDP). Эхний ноот: бергамот, мандарин, ягаан чинжүү.', 'Acqua di Parma''s Sakura Eau de Parfum is a unisex Citrus scent, unveiled in 2019. Its composition begins with top notes of zesty Calabrian bergamot, vibrant Yellow Mandarin, and a hint of spicy Pink Pepper. The heart of the fragrance blooms with delicate Cherry Blossom and exotic Jasmine Sambac, while a warm base of Musk rounds out the olfactory experience.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/76eec4bd-2706-4ca8-aa5d-e21f4139c116.jpg?v=1705700234', 'https://media.sephora.eu/content/dam/gdam/europe/digital/pim/published/A/Acqua_di_Parma/P3910115/49411-media_3.jpg?scaleHeight=750&scaleMode=fit&scaleWidth=750', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-sandalo-edp', 'Acqua di Parma', 'Sandalo', 'EDP', 'unisex', 'woody', NULL, '{"top":["Lemon","Bergamot","Orange","Petitgrain"],"heart":["Lavender","Cardamom"],"base":["Sandalwood","Amber","Tonka bean"]}', 'Acqua di Parma Sandalo: Unisex модлог үнэр (EDP). Эхний ноот: нимбэг, бергамот, жүрж, петигрейн; зүрхний ноот: лаванда, кардамон; суурь ноот: зандан мод, хув, тонка шош.', 'Sandalo Eau de Parfum by Acqua di Parma is a Woody Aromatic fragrance for women and men. This is a new fragrance. Sandalo Eau de Parfum was launched in 2019. Top notes are lemon, calabrian bergamot, orange and petitgrain; middle notes are lavender and cardamom; base notes are sandalwood, amber and tonka bean.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/b3adfae2-ab9c-447b-8392-edacd43240cf_7d2e5f93-8d8f-4998-82bd-48c24944a9f6.jpg?v=1683063586', 'https://cdn.fragrancenet.com/images/photos/600x600/354149.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-vaniglia-edp', 'Acqua di Parma', 'Vaniglia', 'EDP', 'unisex', 'gourmand', NULL, '{"top":["Heliotrope","Neroli","Bergamot","Mandarin"],"heart":["Jasmine","Vanilla"],"base":["Cedar","Musk"]}', 'Acqua di Parma Vaniglia: Unisex гурман үнэр (EDP). Эхний ноот: гелиотроп, нероли, бергамот, мандарин; зүрхний ноот: жасмин, ваниль; суурь ноот: хуш мод, заар.', 'Vaniglia Eau de Parfum, crafted by Acqua di Parma, presents a captivating Amber fragrance suitable for both women and men. Introduced in 2019, this scent opens with vibrant top notes of Heliotrope, Neroli, Calabrian bergamot, and Mandarin Orange. At its heart lie enchanting notes of Vanilla and Jasmine Sambac, while the fragrance concludes with a warm base of Cedar and Musk. Vaniglia is a sun-filled interpretation of vanilla''s intriguing and fascinating notes. The sweet essence of vanilla is extracted from the cloves and combined with notes of bergamot, mandarin, neroli and jasmine sambac for an enveloping and warm composition. An artistic combination celebrating Madagascar''s precious essence. KEY NOTES:', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/files/543937.jpg?v=1745522576', 'https://cdn.fragrancenet.com/images/photos/1600x1600/360178.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-yuzu-edp', 'Acqua di Parma', 'Yuzu', 'EDP', 'unisex', 'citrus', NULL, '{"top":["Bergamot","Sichuan pepper","Yuzu"],"heart":["Mimosa","Lotus","Violet leaf","Jasmine"],"base":["Musk","Licorice","Sandalwood"]}', 'Acqua di Parma Yuzu: Unisex цитрус үнэр (EDP). Эхний ноот: бергамот, сычуань чинжүү, юзу; зүрхний ноот: мимоза, бадамлянхуа, нил цэцгийн навч, жасмин; суурь ноот: заар, чихэр өвс, зандан мод.', 'Yuzu Eau de Parfum by Acqua di Parma is a Citrus Aromatic fragrance for women and men. This is a new fragrance. Yuzu Eau de Parfum was launched in 2019. Top notes are calabrian bergamot, sichuan pepper and yuzu; middle notes are mimosa, lotus, violet leaf and jasmine; base notes are musk, licorice and sandalwood.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/032c146b-e7ad-484b-8367-d72a658c7b0d_91e84ed2-9a73-4290-b689-b07b24b11242.jpg?v=1683063730', 'https://priveperfumes.com/cdn/shop/files/perfume-acqua-di-parma-signature-yuzu-edp-u-100-ml-1-prive-perfumes.webp?v=1775214571&width=1600', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('acqua-di-parma-zafferano-edp', 'Acqua di Parma', 'Zafferano', 'EDP', 'unisex', 'amber', NULL, '{"top":["Bergamot","Bitter orange","Mandarin","Coriander"],"heart":[],"base":["Woods","Vanilla","Tonka bean"]}', 'Acqua di Parma Zafferano: Unisex хув үнэр (EDP). Эхний ноот: бергамот, гашуун жүрж, мандарин, кориандр; суурь ноот: модлог ноот, ваниль, тонка шош.', 'Zafferano by Acqua di Parma is an Amber Floral fragrance designed for both women and men. Introduced in 2022, this modern scent opens with top notes of Bergamot, Bitter Orange, Mandarin Orange, and Coriander. The heart of the fragrance features a blend of Saffron, Orange Blossom, Geranium, Jasmine Sambac, and Rose. The base notes consist of Woody Notes, Vanilla, and Tonka Bean, creating a well-rounded and captivating aroma.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/files/e91a613f-7817-49ec-aead-f59995232cf1.jpg?v=1721766935', 'https://cdn.fragrancenet.com/images/photos/600x600/493401.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('affinessence-collection-notes-de-fond-cedre-iris-edp', 'Affinessence', 'Collection Notes de Fond Cedre Iris', 'EDP', 'unisex', 'woody', NULL, '{"top":[],"heart":[],"base":[]}', 'Affinessence Collection Notes de Fond Cedre Iris: Unisex модлог үнэр (EDP).', 'Affinessence''s Cedre Iris is a unisex scent that falls within the Woody Floral Musk olfactory family. This fragrance was introduced to the market in 2015, with its creation attributed to perfumer Nicolas Bonneville.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/b11ce24c-8316-43c8-a298-cf1d20eb457c.jpg?v=1705089639', 'https://cdn.fragrancenet.com/images/photos/900x900/407166.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('affinessence-collection-notes-de-fond-cuir-curcuma-edp', 'Affinessence', 'Collection Notes de Fond Cuir Curcuma', 'EDP', 'unisex', 'woody', NULL, '{"top":[],"heart":[],"base":[]}', 'Affinessence Collection Notes de Fond Cuir Curcuma: Unisex модлог үнэр (EDP).', 'Launched in 2017, Cuir Curcuma by Affinessence is a unisex Leather perfume. The olfactory creation is the handiwork of perfumer Alexandra Carlin.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/342a1c93-b709-4502-8214-531b0fa21720.jpg?v=1705090034', 'https://cdn.fragrancenet.com/images/photos/1600x1600/407169.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('affinessence-collection-notes-de-fond-vanille-benjoin-edp', 'Affinessence', 'Collection Notes de Fond Vanille Benjoin', 'EDP', 'unisex', 'amber', NULL, '{"top":[],"heart":[],"base":[]}', 'Affinessence Collection Notes de Fond Vanille Benjoin: Unisex хув үнэр (EDP).', 'Affinessence introduced Vanille Benjoin, a unisex Amber Vanilla scent, in 2015. The olfactory creation of Vanille Benjoin is the expert work of perfumer Corinne Cachen.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/02cd8e4f-ccde-40ed-bd22-b9834c613984.jpg?v=1705090394', 'https://img.fragrancex.com/images/products/sku/large/vabaf33.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('affinessence-collection-notes-de-tete-combava-cedrat-edp', 'Affinessence', 'Collection Notes de Tete Combava Cedrat', 'EDP', 'unisex', 'citrus', NULL, '{"top":[],"heart":[],"base":[]}', 'Affinessence Collection Notes de Tete Combava Cedrat: Unisex цитрус үнэр (EDP).', 'Affinessence introduces Combava Cedrat, a unisex scent under the Citrus Aromatic category. Freshly released, this fragrance made its debut in 2022 with the creative expertise of perfumer Nicolas Bonneville. It opens with the invigorating essence of Kaffir Lime at the top, followed by a harmonious blend of Lime and Mint at the heart. The base is a warm fusion of Cardamom and Wood notes, grounding the scent with depth and character.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/b2bf10f7-919b-4573-b254-06b65e7337b3.jpg?v=1705089831', 'https://welzo.com/cdn/shop/files/10049723.jpg?v=1755899182', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-9-pm-edp', 'Afnan', '9 PM', 'EDP', 'men', 'citrus', NULL, '{"top":["Apple","Cinnamon","wild lavender","Bergamot"],"heart":["Orange blossom","Lily-of-the-valley"],"base":["Vanilla","Tonka bean","Amber","Patchouli"]}', 'Afnan 9 PM: Эрэгтэйчүүдэд зориулсан цитрус үнэр (EDP). Эхний ноот: алим, шанцай, зэрлэг лаванда, бергамот; зүрхний ноот: жүржийн цэцэг, хонхон цэцэг; суурь ноот: ваниль, тонка шош, хув, пачули.', 'Afnan 9 PM is a citrus fragrance in EDP concentration. Its listed notes include apple, cinnamon, wild lavender, bergamot, orange blossom.', '/product-photos/curated-097-front.webp', '/product-photos/curated-097-back.webp', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-9-pm-rebel-edp', 'Afnan', '9 PM Rebel', 'EDP', 'unisex', 'aromatic', NULL, '{"top":["Mandarin","Pineapple","Apple"],"heart":[],"base":[]}', 'Afnan 9 PM Rebel: Unisex өвслөг үнэр (EDP). Эхний ноот: мандарин, хан боргоцой, алим.', 'Afnan''s 9 PM Rebel is an Aromatic Fruity fragrance designed for both women and men. This is a recent addition to the fragrance world, having been introduced in 2024. The scent opens with top notes of Mandarin, Pineapple, and Granny Smith apple. The heart of the fragrance features Cedarwood, Vanilla, and Oakmoss, while the base is composed of Ambergris, Dry Wood, Caramel, and Musk.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/files/32540532-2d61-411a-982d-1615e9a86668.jpg?v=1732551814', 'https://coopera.vtexassets.com/arquivos/ids/61561568/17522103604843.jpg?v=638908874838870000', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-9pm-edp', 'Afnan', '9pm', 'EDP', NULL, NULL, 2020, '{"top":["Apple","Cinnamon","Wild Lavender","Bergamot"],"heart":["Orange Blossom","Lily-Of-The-Valley"],"base":["Vanilla","Tonka Bean","Amber","Patchouli"]}', NULL, NULL, 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/afnan-9pm-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/afnan-9pm-edp_back.png', 'draft', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-9pm-elixir-intense-parfum', 'Afnan', '9PM Elixir Intense', 'Parfum', 'unisex', 'amber', NULL, '{"top":["Cardamom","Nutmeg","Elemi","Pimento","Leather","Lavender"],"heart":[],"base":[]}', 'Afnan 9PM Elixir Intense: Unisex хув үнэр (Parfum). Эхний ноот: кардамон, задийн самар, элеми давирхай, пимент, арьс, лаванда.', '9PM Elixir by Afnan is a captivating Oriental Spicy fragrance designed for both women and men. This fresh addition to the fragrance world was introduced in 2025, crafted by the talented nose of Imran Fazlani. The scent opens with enticing top notes of Cardamom, Nutmeg, and Elemi, leading into a heart that features Pimento, Leather, and Lavender. The fragrance concludes with a rich base of Vanilla, Patchouli, Labdanum, and Rock Rose.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/files/1357864.jpg?v=1760634248', 'https://www.mystore.in/s/62ea2c599d1398fa16dbae0a/originals/g/69e0b3524400e80d5db5d21e/afnan-9pm-elixir-1-.jpeg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-her-highness-black-edp', 'Afnan', 'Her Highness Black', 'EDP', 'women', 'woody', NULL, '{"top":[],"heart":[],"base":[]}', 'Afnan Her Highness Black: Эмэгтэйчүүдэд зориулсан модлог үнэр (EDP).', 'Her Highness Black by Afnan Perfume. Every woman can feel like a royalty thanks to Her Highness Black. This tantalizing perfume embodies the confidence bestowed upon a royal with the bold power of self-sufficiency and independence that can turn any woman into the queen of her world. Seductive, bold and sophisticated, this fragrance is a complementary blend of delectable plums immersed in an intoxicating bouquet of tuberose, jasmine and ylang-ylang. A dash of pink pepper kicks the scent up a notch, adding an invigorating spiciness to the long-lasting aroma.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/5378e3f0-542d-444c-8687-c3f0bf935bf5_10ea3ff8-d309-4bb2-acc7-a5f69508f3f5.jpg?v=1683063805', 'https://img.perfume.com/images/products/parent/medium/77893w.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-her-highness-red-edp', 'Afnan', 'Her Highness Red', 'EDP', 'women', 'woody', NULL, '{"top":[],"heart":[],"base":[]}', 'Afnan Her Highness Red: Эмэгтэйчүүдэд зориулсан модлог үнэр (EDP).', 'Her Highness Red Perfume by Afnan, As we walked along the plaza outside the opulent Burj Khalifa, the tallest building in the world, a cool breeze wafted in from the ocean. Evening fell, and we found ourselves dazzled by the Dubai Fountain, perhaps the most extravagant and beautiful man-made water and light show in existence. I’ll never forget that magical evening! Afnan Her Highness Red Perfume captures the enchantment and scents of the best the United Arab Emirates has to offer. Sea salt and a breath of ocean opens the fragrance in a crisp and breathlessly fresh top. Sweet and powdery heliotrope carries the heart, along with undertones of juicy fruits and a bouquet of white florals. Elegant and soft musk creates a memorable base. Unusual and intriguing, this perfume is for women who enjoy romance and a hint of mystery.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/f7920de3-e297-4322-8668-0f7235bab5e0_09769719-bfa3-4431-b2a7-ed5dca2b8610.jpg?v=1759441199', 'https://product-data.raiadrogasil.io/images/17563416.webp', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-highness-iv-red-edp', 'Afnan', 'Highness IV Red', 'EDP', 'unisex', 'aromatic', NULL, '{"top":["Cypress","Bergamot","Lavender"],"heart":["Cedar","Galbanum","Black pepper","Petitgrain"],"base":["Oud","Oakmoss","Leather"]}', 'Afnan Highness IV Red: Unisex өвслөг үнэр (EDP). Эхний ноот: кипарис, бергамот, лаванда; зүрхний ноот: хуш мод, гальбанум, хар чинжүү, петигрейн; суурь ноот: агар мод, царсны хөвд, арьс.', 'His Highness Green by Afnan is a Aromatic Spicy fragrance for men. This is a new fragrance. His Highness Green was launched in 2020. Top notes are Cypress, Bergamot and Lavender; middle notes are Cedar, Galbanum, Black Pepper and Petitgrain; base notes are Agarwood (Oud), Oakmoss and Leather.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/74d8207b-4e5a-435f-8bd0-c7130bf944a8_c98a4102-5f72-42a8-b36b-83b42d35e03c.jpg?v=1683063961', 'https://cdn.notinoimg.com/detail_main_hq/afnan/6290171002239_02-o/highness-iv___230908.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-highness-ix-maroon-edp', 'Afnan', 'Highness IX Maroon', 'EDP', 'unisex', 'aromatic', NULL, '{"top":["Cypress","Bergamot","Lavender"],"heart":["Cedar","Galbanum","Black pepper","Petitgrain"],"base":["Oud","Oakmoss","Leather"]}', 'Afnan Highness IX Maroon: Unisex өвслөг үнэр (EDP). Эхний ноот: кипарис, бергамот, лаванда; зүрхний ноот: хуш мод, гальбанум, хар чинжүү, петигрейн; суурь ноот: агар мод, царсны хөвд, арьс.', 'His Highness Green by Afnan is a Aromatic Spicy fragrance for men. This is a new fragrance. His Highness Green was launched in 2020. Top notes are Cypress, Bergamot and Lavender; middle notes are Cedar, Galbanum, Black Pepper and Petitgrain; base notes are Agarwood (Oud), Oakmoss and Leather.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/59c23eaf-6f89-4429-a0a2-851d6abd2414_cfda72b8-ac22-46af-b94d-7a42cdbf3310.jpg?v=1683064037', 'https://cdn2.jomashop.com/media/catalog/product/a/f/afnan-unisex-highness-ix-maroon-edp-spray-34-oz-tester-fragrances-0000950039655.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-highness-vi-blue-edp', 'Afnan', 'Highness VI Blue', 'EDP', 'unisex', 'aromatic', NULL, '{"top":["Cypress","Bergamot","Lavender"],"heart":["Cedar","Galbanum","Black pepper","Petitgrain"],"base":["Oud","Oakmoss","Leather"]}', 'Afnan Highness VI Blue: Unisex өвслөг үнэр (EDP). Эхний ноот: кипарис, бергамот, лаванда; зүрхний ноот: хуш мод, гальбанум, хар чинжүү, петигрейн; суурь ноот: агар мод, царсны хөвд, арьс.', 'His Highness Green by Afnan is a Aromatic Spicy fragrance for men. This is a new fragrance. His Highness Green was launched in 2020. Top notes are Cypress, Bergamot and Lavender; middle notes are Cedar, Galbanum, Black Pepper and Petitgrain; base notes are Agarwood (Oud), Oakmoss and Leather.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/1b2b0523-5d64-4beb-b5e2-3d2ae265e998_c424f22c-fc59-4336-92a6-6634799bead7.jpg?v=1683064113', 'https://www.perfumenz.co.nz/cdn/shop/products/afnan-highness-vi_1596x1596.png?v=1657842768', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-highness-x-brown-edp', 'Afnan', 'Highness X Brown', 'EDP', 'unisex', 'aromatic', NULL, '{"top":["Cypress","Bergamot","Lavender"],"heart":["Cedar","Galbanum","Black pepper","Petitgrain"],"base":["Oud","Oakmoss","Leather"]}', 'Afnan Highness X Brown: Unisex өвслөг үнэр (EDP). Эхний ноот: кипарис, бергамот, лаванда; зүрхний ноот: хуш мод, гальбанум, хар чинжүү, петигрейн; суурь ноот: агар мод, царсны хөвд, арьс.', 'His Highness Green by Afnan is a Aromatic Spicy fragrance for men. This is a new fragrance. His Highness Green was launched in 2020. Top notes are Cypress, Bergamot and Lavender; middle notes are Cedar, Galbanum, Black Pepper and Petitgrain; base notes are Agarwood (Oud), Oakmoss and Leather.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/2e26c965-0f52-44f1-b8fa-87603b76313c_6d316122-d57c-4108-aeb6-8c17e3edb752.jpg?v=1683064188', 'https://www.perfumenz.co.nz/cdn/shop/products/afnan-highness-x_grande.png?v=1669000590', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-his-highness-green-edp', 'Afnan', 'His Highness Green', 'EDP', 'men', 'woody', NULL, '{"top":["Nutmeg","Cardamom","Cumin","Pink pepper"],"heart":["Geranium","Myrrh"],"base":["Cedar","Sandalwood","Patchouli"]}', 'Afnan His Highness Green: Эрэгтэйчүүдэд зориулсан модлог үнэр (EDP). Эхний ноот: задийн самар, кардамон, зира, ягаан чинжүү; зүрхний ноот: герань, мирра; суурь ноот: хуш мод, зандан мод, пачули.', 'This is a masculine warm spicy fragrance for men. Rich high quality notes are brought together to give you an experience of greatness. Sensual and robust in nature, you will enjoy every minute of this high end cologne.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/d4ac7f96-c999-4016-807b-e52c97217fb7_eedc01b1-7607-4890-81d7-35c8d9ba8015.jpg?v=1683064264', 'https://www.essenza.ng/cdn/shop/products/9a9964696e4d05cf8524eb5a0724f6b24e0f7625_1024x.jpg?v=1722415941', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-his-highness-white-edp', 'Afnan', 'His Highness White', 'EDP', 'men', 'woody', NULL, '{"top":["Cardamom","Pink pepper","Cumin","Nutmeg","Saffron"],"heart":["Geranium"],"base":["Patchouli","Incense"]}', 'Afnan His Highness White: Эрэгтэйчүүдэд зориулсан модлог үнэр (EDP). Эхний ноот: кардамон, ягаан чинжүү, зира, задийн самар, гүргэм; зүрхний ноот: герань; суурь ноот: пачули, хүж.', 'His Highness White Cologne by Afnan, Exude confidence and masculinity with each and every step by incorporating His Highness White, a smooth, sweet cologne, into your everyday wardrobe. This unique fragrance opens up with top notes of cardamom, pink pepper, cumin, nutmeg, saffron, pink pepper. The middle notes offer a softer experience, with floral touches of geranium and a dash of spicy myrrh. Base notes include touches of patchouli, incense, almond, musk and sandalwood, creating a smoky and spicy finish unlike any other. This well-loved fragrance is ideal for chilly days and upscale occasions of all types.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/52c8ee37-aa51-4d33-8e85-7fb1f87054db_67b68e94-8a57-40af-8da6-ce42af656423.jpg?v=1683064346', 'https://fvfperfumes.com/cdn/shop/files/AfnanHisHighnessWhiteEDP2_M.jpg?v=1744089649&width=533', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-mirsaal-of-trust-edp', 'Afnan', 'Mirsaal of Trust', 'EDP', 'men', 'amber', NULL, '{"top":["Vetiver","Ambroxan","Raspberry","Saffron"],"heart":["Raspberry","Saffron"],"base":[]}', 'Afnan Mirsaal of Trust: Эрэгтэйчүүдэд зориулсан хув үнэр (EDP). Эхний ноот: ветивер, амброксан, бөөрөлзгөнө, гүргэм; зүрхний ноот: бөөрөлзгөнө, гүргэм.', 'Afnan''s Mirsaal of Trust is a warm and spicy fragrance specifically created for men and released in 2020. Its top notes are composed of Vetiver and Ambroxan, while the middle notes blend Raspberry and Saffron. Finally, a luxurious blend of Cashmere Wood, Carnation and Amber form the base of this scent.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/c3eecff3-3c8b-4a8a-a7fe-34093dc868ea_64c54685-1d2b-459c-8149-8140a8dcaafa.jpg?v=1691167985', 'https://beautyhouse.com/cdn/shop/files/04qk8lso0c.png?v=1723878625&width=1600', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-ornament-edp', 'Afnan', 'Ornament', 'EDP', 'men', 'woody', NULL, '{"top":["Apple","Cardamom","Clove","Nutmeg"],"heart":["Saffron","Black pepper","Geranium"],"base":["Amber","Patchouli","Cedar","Sandalwood"]}', 'Afnan Ornament: Эрэгтэйчүүдэд зориулсан модлог үнэр (EDP). Эхний ноот: алим, кардамон, гвоздик, задийн самар; зүрхний ноот: гүргэм, хар чинжүү, герань; суурь ноот: хув, пачули, хуш мод, зандан мод.', 'Ornament Pour Homme by Afnan is a Woody Aromatic fragrance for men. Ornament Pour Homme was launched in 2014. Top notes are Apple, Cardamom, Clove and Nutmeg; middle notes are Saffron, Pepper and Geranium; base notes are Amber, Patchouli, Cedar and Sandalwood.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/c03d0f92-0c9b-4fd2-a107-5ccaffb645a5_b00ccf21-a77b-497f-a637-5a4f7609cd0b.jpg?v=1683737110', 'https://www.perfumenz.co.nz/cdn/shop/products/afnan-ornament-men_700x700.png?v=1655263490', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-souvenir-desert-rose-edp', 'Afnan', 'Souvenir Desert Rose', 'EDP', 'women', 'woody', NULL, '{"top":["Fruity notes","Sweet notes","Musk"],"heart":["Powdery notes","Tropical fruits"],"base":["Sandalwood","Citrus notes","Amber"]}', 'Afnan Souvenir Desert Rose: Эмэгтэйчүүдэд зориулсан модлог үнэр (EDP). Эхний ноот: жимсний ноот, чихэрлэг ноот, заар; зүрхний ноот: пудрын ноот, халуун орны жимс; суурь ноот: зандан мод, цитрусын ноот, хув.', 'Feminine perfume with fruity notes, musk, sandalwood and amber.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/908924ac-1bd5-48c5-a574-4093a32661e8_93b0a839-b50a-4db6-afb9-c55d71a08952.jpg?v=1683064878', 'https://priveperfumes.com/cdn/shop/files/afnan-souvenir-desert-rose-edp-w-1-prive-perfumes.jpg?v=1782206193&width=1024', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-souvenir-floral-bouquet-edp', 'Afnan', 'Souvenir Floral Bouquet', 'EDP', 'women', 'woody', NULL, '{"top":["Lychee","Rhubarb","Bergamot"],"heart":["Rose","Lily-of-the-valley","Peony","Vanilla"],"base":["Musk","Cashmere wood","Amber"]}', 'Afnan Souvenir Floral Bouquet: Эмэгтэйчүүдэд зориулсан модлог үнэр (EDP). Эхний ноот: личи, гишүүнэ, бергамот; зүрхний ноот: сарнай, хонхон цэцэг, цээнэ цэцэг, ваниль; суурь ноот: заар, кашмир мод, хув.', 'Floral feminine perfume.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/f2804137-6a2e-46a0-84b5-7a77979080b1_9dd77bc4-92d2-4a28-93fd-f872843d9f2c.jpg?v=1683064958', 'https://labelleperfumes.com/cdn/shop/files/AFNAN-SOUVENIR-FLORAL-BOUQUET-1_1080x.webp', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-supremacy-gold-edp', 'Afnan', 'Supremacy Gold', 'EDP', 'unisex', 'amber', NULL, '{"top":["Violet","Nutmeg","Peach blossom","Cumin"],"heart":["Patchouli","Iris"],"base":["Vanilla","Oud","Amber","Benzoin"]}', 'Afnan Supremacy Gold: Unisex хув үнэр (EDP). Эхний ноот: нил цэцэг, задийн самар, тоорын цэцэг, зира; зүрхний ноот: пачули, цахилдаг; суурь ноот: ваниль, агар мод, хув, бензойн.', 'Supremacy Gold by Afnan Perfumes is a Oriental fragrance for women and men. Supremacy Gold was launched in 2013. Top notes are Violet, Nutmeg, Peach Blossom and Cumin; middle notes are Patchouli and iris; base notes are Vanilla, Agarwood (Oud), Amber and Benzoin.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/ff00f4f4-41e0-438c-a8f6-1f7ed5d31a47_252c36cf-3605-466d-8f21-4af83d9acd86.jpg?v=1683065036', 'https://cdn.miswag.me/images/images/a0a46867-fe8e-46fb-8706-fe1df5390586.jpeg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-supremacy-in-heaven-edp', 'Afnan', 'Supremacy In Heaven', 'EDP', 'men', 'amber', NULL, '{"top":["Bergamot","Mandarin"],"heart":["Green tea","Blackcurrant"],"base":["Musk","Sandalwood","Woods"]}', 'Afnan Supremacy In Heaven: Эрэгтэйчүүдэд зориулсан хув үнэр (EDP). Эхний ноот: бергамот, мандарин; зүрхний ноот: ногоон цай, үхрийн нүд; суурь ноот: заар, зандан мод, модлог ноот.', 'Supremacy in Heaven is a perfume by Afnan Perfumes for women and men and was released in 2018. The scent is green-citrusy', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/a5d86c18-98fd-41d8-b8cb-5e895219520a_9741d08c-d931-4aa1-8da5-dee59c5df67e.jpg?v=1683065194', 'https://www.sobelia.com/35000-50208/supremacy-in-heaven-afnan-eau-de-parfum-spray-100ml.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-supremacy-in-oud-extrait', 'Afnan', 'Supremacy In Oud', 'Extrait', 'unisex', 'aromatic', NULL, '{"top":["Saffron","Nutmeg","Lavender"],"heart":["Oud","Sweet notes"],"base":["Patchouli","Musk"]}', 'Afnan Supremacy In Oud: Unisex өвслөг үнэр (Extrait). Эхний ноот: гүргэм, задийн самар, лаванда; зүрхний ноот: агар мод, чихэрлэг ноот; суурь ноот: пачули, заар.', 'Supremacy in Oud by Afnan Perfumes is a Aromatic Spicy fragrance for women and men. This is a new fragrance. Supremacy in Oud was launched in 2021. Top notes are Saffron, Nutmeg and Lavender; middle notes are Agarwood (Oud) and Sweet Notes; base notes are Patchouli and Musk.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/7e921156-e0db-442b-8efe-4790f4fbd42f.jpg?v=1683065281', 'https://productosdelujo.cl/cdn/shop/files/Disenosintitulo_59_edc3cc59-5e52-4f44-aeba-b8e6e536e87f.jpg?v=1703341513&width=1214', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-supremacy-incense-edp', 'Afnan', 'Supremacy Incense', 'EDP', 'men', 'amber', NULL, '{"top":["Bergamot","Oregano"],"heart":["Amber","Labdanum","Opoponax"],"base":["Leather","Smoky notes","Patchouli","Oud"]}', 'Afnan Supremacy Incense: Эрэгтэйчүүдэд зориулсан хув үнэр (EDP). Эхний ноот: бергамот, орегано; зүрхний ноот: хув, лабданум, опопонакс; суурь ноот: арьс, утаат ноот, пачули, агар мод.', 'Supremacy Incense - is a burning heat, embracing passion and alluring sensuality. The warm spice at the beginning shows a spicy oregano combined with a slightly bitter bergamot, into which the majestic, velvety ambergris melts the honey heat. Crispy green apple and seductive blackcurrant stalked with delicious pineapple are added. The softness of the trees embraces and attracts, but at the same time deepens the aroma especially with the touches of oud oil, whose chords are smooth in this composition. The echoes of flowers, headed by roses and Moroccan jasmine, float to the trees. Smoke from smoldering rare trees, skin with undertones of apricots and a sensual musk charge, accompanied by a few nuances of vanilla pods, enters the scene. The final parade shows earthy shades of oak moss, herbal spice patchouli with bitterly leathery labdan, whose interconnected smell will make a special touch of mystery.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/6efd2439-edcd-482c-ac9d-4cf821e82d67_f596abe7-9cf0-4b50-8218-77c88af464d0.jpg?v=1683065115', 'https://cdn.fragrancenet.com/images/photos/900x900/377335.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-supremacy-noir-edp', 'Afnan', 'Supremacy Noir', 'EDP', 'men', 'amber', NULL, '{"top":["Spruce","Violet","Bergamot"],"heart":["Pine","Leather","Lavender"],"base":["Labdanum","Patchouli"]}', 'Afnan Supremacy Noir: Эрэгтэйчүүдэд зориулсан хув үнэр (EDP). Эхний ноот: гацуур, нил цэцэг, бергамот; зүрхний ноот: нарс, арьс, лаванда; суурь ноот: лабданум, пачули.', 'Supremacy Noir by Afnan Perfumes is a Oriental Spicy fragrance for women and men. Supremacy Noir was launched in 2015. Top notes are Spruce, Violet and Bergamot; middle notes are Pine Tree, Leather and Lavender; base notes are Labdanum and Patchouli.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/34504215-b648-4c90-a419-e42af9e7a495_6cb20107-b128-4441-9625-9e260b65a292.jpg?v=1683065384', 'https://www.oudnaroma.com/cdn/shop/files/d03f85cd-7d91-49db-8377-e4dfaaa0df7b_3442ce51-f1db-49a4-a8a9-b0d37fd25775.jpg?v=1763918598&width=1080', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-supremacy-not-only-intense-extrait', 'Afnan', 'Supremacy Not Only Intense', 'Extrait', 'men', 'amber', 2021, '{"top":["Black Currant","Bergamot","Apple"],"heart":["Oakmoss","Patchouli","Lavender"],"base":["Ambergris","Musk","Saffron"]}', 'Afnan Supremacy Not Only Intense: Эрэгтэйчүүдэд зориулсан хув үнэр (Extrait). Эхний ноот: үхрийн нүд, бергамот, алим; зүрхний ноот: царсны хөвд, пачули, лаванда; суурь ноот: амбра, гүргэм, заар.', 'Supremacy Not Only Intense by Afnan Perfumes is a Amber Spicy fragrance for men. This is a new fragrance. Supremacy Not Only Intense was launched in 2021. Top notes are Black Currant, Bergamot and Apple; middle notes are Oakmoss, Patchouli and Lavender; base notes are Ambergris, Saffron and Musk.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/afnan-supremacy-not-only-intense-extrait_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/afnan-supremacy-not-only-intense-extrait_back.png', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-supremacy-pink-edp', 'Afnan', 'Supremacy Pink', 'EDP', 'women', 'amber', NULL, '{"top":["Pink pepper","Violet"],"heart":["Rose","Peony","Lily-of-the-valley"],"base":["Musk","Amber"]}', 'Afnan Supremacy Pink: Эмэгтэйчүүдэд зориулсан хув үнэр (EDP). Эхний ноот: ягаан чинжүү, нил цэцэг; зүрхний ноот: сарнай, цээнэ цэцэг, хонхон цэцэг; суурь ноот: заар, хув.', 'Floral & Fruity', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/c5108209-f39a-402c-b839-8f9aa334e079_30dc6ab8-458d-4e49-a26c-f4b90782d874.jpg?v=1683065670', 'https://cdn.notinoimg.com/detail_main_hq/afnan/afnspim_aedp10_02/afnan-supremacy-pour-femme-pink-eau-de-parfum-fur-damen___170914.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-supremacy-purple-edp', 'Afnan', 'Supremacy Purple', 'EDP', 'women', 'amber', NULL, '{"top":["Fruity notes","Citrus notes","Musk","Amber","Vanilla"],"heart":["Musk","Amber","Vanilla"],"base":["Musk","Vanilla"]}', 'Afnan Supremacy Purple: Эмэгтэйчүүдэд зориулсан хув үнэр (EDP). Эхний ноот: жимсний ноот, цитрусын ноот, заар, хув, ваниль; зүрхний ноот: заар, хув, ваниль; суурь ноот: заар, ваниль.', 'Afnan''s Supremacy Purple is an Amber-scented perfume for women, featuring top notes of Fruits and Citruses, middle notes of Musk and Amber, and base notes of Musk and Vanilla.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/aa9ec4d8-f148-4de1-ac37-a537acad8ca2_eac3b094-538c-43d2-bf4c-cf1ee6352233.jpg?v=1759467099', 'https://fragrancebaba.com/cdn/shop/files/GUEST_210991ba-e1b3-4cf1-8b51-ecb95ee96525.jpg?v=1762777872&width=1946', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-supremacy-silver-edp', 'Afnan', 'Supremacy Silver', 'EDP', 'men', 'woody', 2013, '{"top":["Pineapple","Black Currant","Bergamot","Apple"],"heart":["Birch","Patchouli","Moroccan Jasmine","Rose"],"base":["Musk","Oakmoss","Ambergris","Vanilla"]}', 'Afnan Supremacy Silver: Эрэгтэйчүүдэд зориулсан модлог үнэр (EDP). Эхний ноот: алим, бергамот, үхрийн нүд, хан боргоцой; зүрхний ноот: сарнай, хус мод, жасмин, пачули; суурь ноот: царсны хөвд, заар, амбра, ваниль.', 'Supremacy Silver by Afnan Perfumes is a Woody Floral Musk fragrance for men. Supremacy Silver was launched in 2013. Top notes are apple, bergamot, black currant and pineapple; middle notes are rose, birch, moroccan jasmine and patchouli; base notes are oakmoss, musk, ambergris and vanilla. Supremacy Silver is a woody-floral-musk men’s scent that launched in 2013 from the Afnan Perfumes brand. This refreshing fragrance shows off your sensual, masculine side the moment you enter a room, without overpowering those present. Citrusy top notes include luscious apple, blackcurrant, pineapple and bergamot. Refreshing, oriental, and woody fragrance leaves you feeling cool and confident Ideal for a variety of occasions A fragrance that has been widely accepted It’s light, refreshing and can be applied often. fragrance to make it last longer.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/afnan-supremacy-silver-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/afnan-supremacy-silver-edp_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-tobacco-rush-edp', 'Afnan', 'Tobacco Rush', 'EDP', 'unisex', 'woody', NULL, '{"top":[],"heart":[],"base":[]}', 'Afnan Tobacco Rush: Unisex модлог үнэр (EDP).', 'A new addition to the world of fragrances, Tobacco Rush by Afnan was released in 2022. Described as a Leather scent, it is suitable for both women and men. Its fragrance notes are comprised of a heady mix of Tobacco, Spicy Notes, Woody Notes, Sweet Notes, Lavender, Agarwood (Oud), Amber and Cedar.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/3b985421-4422-499a-b851-28f1cb1d6dfa.jpg?v=1759467103', 'https://www.navishperfume.com/cdn/shop/files/IMG-5061.jpg?v=1757607397&width=1445', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('afnan-turathi-blue-edp', 'Afnan', 'Turathi Blue', 'EDP', 'men', 'citrus', 2021, '{"top":["Citruses"],"heart":["Amber","Woodsy Notes"],"base":["Musk","Patchouli","Spices"]}', 'Afnan Turathi Blue: Эрэгтэйчүүдэд зориулсан цитрус үнэр (EDP). Эхний ноот: цитрусын ноот; зүрхний ноот: хув, модлог ноот; суурь ноот: заар, пачули, хар чинжүү.', 'Afnan Turathi Blue is a citrus fragrance in EDP concentration. Its listed notes include citrus notes, amber, woods, musk, patchouli.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/afnan-turathi-blue-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/afnan-turathi-blue-edp_back.png', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('agatho-parfum-195-a-c-edp', 'Agatho Parfum', '195 A.C.', 'EDP', 'unisex', 'amber', NULL, '{"top":[],"heart":[],"base":[]}', 'Agatho Parfum 195 A.C.: Unisex хув үнэр (EDP).', '195 a.C. by Agatho Parfum is a fragrance for women and men. 195 a.C. was launched in 2019. The nose behind this fragrance is Maurizio Cerizza.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/files/d87dd4eb-48fd-4eb4-a482-a9672756a35a.jpg?v=1711382209', 'https://cdn.fragrancenet.com/images/photos/1600x1600/428667.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('agatho-parfum-castiamanti-edp', 'Agatho Parfum', 'Castiamanti', 'EDP', 'unisex', 'amber', NULL, '{"top":["Saffron","Laurel","Myrtle"],"heart":["Rose","Jasmine"],"base":["Vanilla","Oud","Incense","Amber","Labdanum","Musk"]}', 'Agatho Parfum Castiamanti: Unisex хув үнэр (EDP). Эхний ноот: гүргэм, лаврын навч, мирт; зүрхний ноот: сарнай, жасмин; суурь ноот: ваниль, агар мод, хүж, хув, лабданум, заар.', 'Castiamanti by Agatho Parfum is a Amber Vanilla fragrance for women and men. Castiamanti was launched in 2019. The nose behind this fragrance is Maurizio Cerizza. Top notes are Saffron, Laurels and Myrtle; middle notes are Rose and Jasmine; base notes are Vanilla, Agarwood (Oud), Incense, Amber, Labdanum and White Musk.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/files/4e229ff7-5406-4857-a962-dc2dd58a1695.jpg?v=1711382242', 'https://www.thescentsstore.com/cdn/shop/products/428666.jpg?v=1753701034', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('ajmal-amber-musc-edp', 'Ajmal', 'Amber Musc', 'EDP', 'unisex', 'amber', NULL, '{"top":[],"heart":[],"base":[]}', 'Ajmal Amber Musc: Unisex хув үнэр (EDP).', 'Amber Musc by Ajmal is a Amber Floral fragrance for women and men. Amber Musc was launched in 2015. The nose behind this fragrance is Abdulla Ajmal.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/efe763da-9806-461c-9037-910ef8962a84_4a87df2b-2ff7-4cf8-b0c2-1c6ffdfe5135.jpg?v=1683066470', 'https://kristall-parfum.ru/image/catalog/product/ajmal/ajmal-amber-musc-100-ml-edp_1.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('ajmal-evoke-gold-edp', 'Ajmal', 'Evoke Gold', 'EDP', 'men', 'woody', NULL, '{"top":[],"heart":["Iris","Amber","Geranium"],"base":[]}', 'Ajmal Evoke Gold: Эрэгтэйчүүдэд зориулсан модлог үнэр (EDP). Зүрхний ноот: цахилдаг, хув, герань.', 'Ajmal''s Evoke Gold For Him is a masculine Woody Aromatic scent that debuted in 2018. Its opening notes are Neroli and Pepper, while its middle notes are a combination of Orris Root, Amber, and Geranium. To complete the fragrance, its base is composed of Cedar and Patchouli.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/f60e00c1-a11f-4fe6-92e9-fc7d83391e11.jpg?v=1691178091', 'https://www.perfumenz.co.nz/cdn/shop/products/ajmal-evoke-gold_700x700.png?v=1649800834', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('akro-bake-edp', 'Akro', 'Bake', 'EDP', NULL, NULL, 2023, '{"top":["Lemon Zest","Rum"],"heart":["Whipped Cream","Praline"],"base":["Bourbon Vanilla","Brown Sugar"]}', NULL, NULL, 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/akro-bake-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/akro-bake-edp_back.png', 'draft', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('akro-ink-edp', 'Akro', 'Ink', 'EDP', 'unisex', 'floral', NULL, '{"top":[],"heart":[],"base":[]}', 'Akro Ink: Unisex цэцэгсийн үнэр (EDP).', 'Ink by Akro is a unisex Floral scent that has recently entered the market. Released in 2022, this fresh addition to the fragrance world was expertly crafted by perfumer Olivier Cresp.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/770d8ae2-a1d7-4012-aed4-9cc4226fe914.jpg?v=1705010525', 'https://beautyhouse.com/cdn/shop/files/02waolokvm.png?v=1762196441&width=954', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('akro-malt-edp', 'Akro', 'Malt', 'EDP', 'unisex', 'woody', NULL, '{"top":[],"heart":[],"base":[]}', 'Akro Malt: Unisex модлог үнэр (EDP).', 'Malt, a Leather-scented fragrance for both men and women, was released in 2018 by Akro. It was created by renowned perfumer Olivier Cresp.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/ad97f0b7-41e8-401e-b9bf-b3ebaa50b493.jpg?v=1695315737', 'https://cs-a.ecimg.tw/items/DDAHMDA900J3TE5/000001_1754468425.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('akro-night-edp', 'Akro', 'Night', 'EDP', 'unisex', 'amber', NULL, '{"top":[],"heart":[],"base":[]}', 'Akro Night: Unisex хув үнэр (EDP).', 'Akro''s Smoke, created by nose Olivier Cresp and released in 2018, is a unisex fragrance with an Amber Woody scent.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/02efa5f9-b421-429a-addb-4ebc62aa4161.jpg?v=1695315915', 'https://beautyhouse.com/cdn/shop/files/02pf74gb08.png?v=1762196762&width=951', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('al-haramain-amber-musk-edp', 'Al Haramain', 'Amber Musk', 'EDP', 'unisex', 'amber', NULL, '{"top":["Amber","Musk","Oud"],"heart":["Raspberry","Rose","Birch","Saffron"],"base":["Amberwood","Geranium","Benzoin"]}', 'Al Haramain Amber Musk: Unisex хув үнэр (EDP). Эхний ноот: хув, заар, агар мод; зүрхний ноот: бөөрөлзгөнө, сарнай, хус мод, гүргэм; суурь ноот: хув мод, герань, бензойн.', 'Amber Musk by Al Haramain Perfumes is a fragrance for women and men. This is a new fragrance. Amber Musk was launched in 2021. Top notes are Amber, Musk and Agarwood (Oud); middle notes are Raspberry, Rose, Birch and Saffron; base notes are Amberwood, Geranium and Benzoin.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/4567ef63-6661-4d36-a41a-0b5460b9273c_577fc3c3-5109-4174-9106-4edb43640d00.jpg?v=1683067690', 'https://cdn.fragrancenet.com/images/photos/900x900/458626.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('al-haramain-amber-oud-black-edition-edp', 'Al Haramain', 'Amber Oud Black Edition', 'EDP', 'unisex', 'amber', NULL, '{"top":["Rosemary","Bergamot","Cedar","Lemon"],"heart":["Black pepper","Cedar","Guaiac wood"],"base":["Resins","Amber","Musk"]}', 'Al Haramain Amber Oud Black Edition: Unisex хув үнэр (EDP). Эхний ноот: розмарин, бергамот, хуш мод, нимбэг; зүрхний ноот: хар чинжүү, хуш мод, гваяк мод; суурь ноот: давирхай, хув, заар.', 'Amber Oud by Al Haramain Perfumes is a Amber Woody fragrance for women and men. Amber Oud was launched in 2018. Top notes are Rosemary, Bergamot, Cedar and Lemon; middle notes are Spices, Cedar and Guaiac Wood; base notes are resins, Amber and Musk.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/9f717eac-8118-4bd0-9735-078dfb506c50_582cd955-90f0-4f4e-bd34-c6e2a483a759.jpg?v=1683067760', 'https://pardohogar.vtexassets.com/arquivos/ids/820434/image-05d9eed5b6de4fb58aff4c74ffde0d5c.jpg?v=638997831085270000', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('al-haramain-amber-oud-bleu-edition-edp', 'Al Haramain', 'Amber Oud Bleu Edition', 'EDP', 'unisex', 'amber', NULL, '{"top":["Grapefruit","Pink pepper","Mint","Lemon"],"heart":["Vetiver","Ginger","Jasmine"],"base":["Sandalwood","Patchouli","Incense","Cedar"]}', 'Al Haramain Amber Oud Bleu Edition: Unisex хув үнэр (EDP). Эхний ноот: бэрсүүт жүрж, ягаан чинжүү, гаа, нимбэг; зүрхний ноот: ветивер, цагаан гаа, жасмин; суурь ноот: зандан мод, пачули, хүж, хуш мод.', 'Amber Oud Bleu Edition by Al Haramain Perfumes is a fragrance for women and men. This is a new fragrance. Amber Oud Bleu Edition was launched in 2022. Top notes are Grapefruit, Pink Pepper, Mint and Lemon; middle notes are Vetiver, Ginger and Jasmine; base notes are Sandalwood, Patchouli, Olibanum and Cedar.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/7f544716-484d-40dd-b540-89afed8495a1_a1b610f7-177c-47de-97a0-ba0b05ddff64.jpg?v=1683067834', 'https://http2.mlstatic.com/D_NQ_NP_890240-MLM71391214043_082023-O-al-haramain-amber-oud-bleu-edition-edp-200-ml-unisex.webp', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('al-haramain-amber-oud-carbon-edition-edp', 'Al Haramain', 'Amber Oud Carbon Edition', 'EDP', 'unisex', 'woody', NULL, '{"top":["Bergamot","Lavender","Rosemary"],"heart":["Marine notes","Geranium","Sage"],"base":["Moss","Cedar","Vetiver","Amber"]}', 'Al Haramain Amber Oud Carbon Edition: Unisex модлог үнэр (EDP). Эхний ноот: бергамот, лаванда, розмарин; зүрхний ноот: далайн ноот, герань, мэргэн өвс; суурь ноот: хөвд, хуш мод, ветивер, хув.', 'Amber Oud Carbon Edition by Al Haramain Perfumes is a Woody Aromatic fragrance for women and men. This is a new fragrance. Amber Oud Carbon Edition was launched in 2022. Top notes are Bergamot, Lavender and Rosemary; middle notes are Sea Notes, Geranium and Sage; base notes are Moss, Cedar, Vetiver and Amber.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/16a14ae3-2a52-4313-8d13-185904c9cf96_321a898f-1446-46ee-97e9-8b17001234a9.jpg?v=1683067912', 'https://cd3c14-whites.akinoncloudcdn.com/products/2025/09/10/44536/eb27311e-1152-4474-a544-e3e9faa8a338_size2048x2048_cropCenter.jpg', 'active', 'content') ON CONFLICT(id) DO NOTHING;
