INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('al-haramain-amber-oud-exclusif-sport-extrait-the-extrait', 'Al Haramain', 'Amber Oud Exclusif Sport Extrait the', 'Extrait', 'unisex', 'amber', NULL, '{"top":["Saffron"],"heart":[],"base":["Ambergris","Musk","Cedar"]}', 'Al Haramain Amber Oud Exclusif Sport Extrait the: Unisex хув үнэр (Extrait). Эхний ноот: гүргэм; суурь ноот: амбра, заар, хуш мод.', 'Amber Oud Exclusif Sport Extrait de Parfum by Al Haramain Perfumes is a Amber Floral fragrance for women and men. Amber Oud Sport was launched in 2019. Top note is saffron. Middle note is Jasmine. Base notes are ambergris, musk and white cedar extract.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/5e6cece5-f3eb-4393-a52f-590c2de7a293.jpg?v=1683068684', 'https://cdn2.jomashop.com/media/catalog/product/cache/fde19e4197824625333be074956e7640/a/l/al-haramain-mens-amber-oud-exclusif-sport-edp-20-oz-fragrances-3760327810030.jpg?height=546&width=546', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('al-haramain-amber-oud-gold-edition-edp', 'Al Haramain', 'Amber Oud Gold Edition', 'EDP', 'unisex', 'amber', NULL, '{"top":["Bergamot","Green notes"],"heart":["Melon","Sweet notes","Pineapple","Amber"],"base":["Vanilla","Musk","Woods"]}', 'Al Haramain Amber Oud Gold Edition: Unisex хув үнэр (EDP). Эхний ноот: бергамот, ногоон ноот; зүрхний ноот: амтат гуа, чихэрлэг ноот, хан боргоцой, хув; суурь ноот: ваниль, заар, модлог ноот.', 'Amber Oud Gold Edition by Al Haramain Perfumes is a Amber Vanilla fragrance for women and men. This is a new fragrance. Amber Oud Gold Edition was launched in 2018. Top notes are Bergamot and Green Notes; middle notes are Melon, Sweet Notes, Pineapple and Amber; base notes are Vanilla, Musk and Woody Notes. Amber Oud Gold Edition by Al Haramain Perfumes is a Amber Vanilla fragrance for women and men. Amber Oud Gold Edition was launched in 2018. Top notes are Bergamot and Green Notes. Middle notes are Melon, Sweet Notes, Pineapple and Amber. Base notes are Musk, Vanilla and Woody Notes.', 'https://cdn.shopify.com/s/files/1/0288/9875/4698/products/c5178dd0-0257-4cfc-a736-6dd6a3c3a00b.jpg?v=1683068298', 'https://a.allegroimg.com/original/11073d/72bee5a94a499b7116796e864809/AL-HARAMAIN-AMBER-OUD-GOLD-EDITION-EDP-woda-perfumowana-unisex-60-ml', 'active', 'content') ON CONFLICT(id) DO NOTHING;
