INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('azzaro-the-most-wanted-intense-edp', 'Azzaro', 'The Most Wanted Intense', 'EDP', 'men', 'amber', NULL, '{"top":["Cardamom"],"heart":["Toffee"],"base":["Amberwood"]}', 'Azzaro The Most Wanted Intense: Эрэгтэйчүүдэд зориулсан хув үнэр (EDP). Эхний ноот: кардамон; зүрхний ноот: ирис чихэр; суурь ноот: хув мод.', 'Azzaro The Most Wanted Intense is a amber fragrance in EDP concentration. Its listed notes include cardamom, toffee, amberwood.', '/product-photos/curated-018-front.webp', NULL, 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('azzaro-the-most-wanted-parfum', 'Azzaro', 'The Most Wanted', 'Parfum', 'men', 'woody', NULL, '{"top":["Grapefruit","Italian Mandarin Orange","Pink Pepper"],"heart":["Rose","Raspberry","Violet"],"base":["Cedar","Iris","Musk","Sandalwood"]}', 'Azzaro The Most Wanted: Эрэгтэйчүүдэд зориулсан модлог үнэр (Parfum). Эхний ноот: цагаан гаа; зүрхний ноот: модлог ноот; суурь ноот: ваниль.', 'Azzaro The Most Wanted is a woody fragrance in Parfum concentration. Its listed notes include ginger, woods, vanilla.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/azzaro-the-most-wanted-parfum_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/azzaro-the-most-wanted-parfum_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
