INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('carolina-herrera-good-girl-blush-edp', 'Carolina Herrera', 'Good Girl Blush', 'EDP', 'women', 'woody', 2023, '{"top":["Bergamot","Bitter Almond"],"heart":["Peony","Ylang-Ylang"],"base":["Vanilla","Coumarin"]}', 'Carolina Herrera Good Girl Blush: Эмэгтэйчүүдэд зориулсан модлог үнэр (EDP). Эхний ноот: бергамот, гашуун бүйлс; зүрхний ноот: цээнэ цэцэг, иланг-иланг; суурь ноот: ваниль, кумарин.', 'Carolina Herrera Good Girl Blush is a woody fragrance in EDP concentration. Its listed notes include bergamot, bitter almond, peony, ylang-ylang, vanilla.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/carolina-herrera-good-girl-blush-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/carolina-herrera-good-girl-blush-edp_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('carolina-herrera-good-girl-edp', 'Carolina Herrera', 'Good Girl', 'EDP', 'women', 'gourmand', 2016, '{"top":["Almond","Coffee","Bergamot","Lemon"],"heart":["Tuberose","Jasmine Sambac","Orange Blossom","Orris","Bulgarian Rose"],"base":["Tonka Bean","Cacao","Vanilla","Praline","Sandalwood","Musk","Amber","Cashmere Wood","Cinnamon","Patchouli","Cedar"]}', 'Carolina Herrera Good Girl: Эмэгтэйчүүдэд зориулсан гурман үнэр (EDP). Эхний ноот: бүйлс, кофе, бергамот, нимбэг; зүрхний ноот: тубероз, жасмин, жүржийн цэцэг, цахилдаг, сарнай; суурь ноот: тонка шош, какао, ваниль, пралине, зандан мод, заар, хув, кашмир мод.', 'Carolina Herrera Good Girl is a gourmand fragrance in EDP concentration. Its listed notes include almond, coffee, bergamot, lemon, tuberose.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/carolina-herrera-good-girl-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/carolina-herrera-good-girl-edp_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
