INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('carolina-herrera-very-good-girl-edp', 'Carolina Herrera', 'Very Good Girl', 'EDP', 'women', 'floral', 2021, '{"top":["Litchi","Red Currant"],"heart":["Rose"],"base":["Vanilla","Vetiver"]}', 'Carolina Herrera Very Good Girl: Эмэгтэйчүүдэд зориулсан цэцэгсийн үнэр (EDP). Эхний ноот: личи, улаан үхрийн нүд; зүрхний ноот: сарнай; суурь ноот: ваниль, ветивер.', 'Carolina Herrera Very Good Girl is a floral fragrance in EDP concentration. Its listed notes include lychee, red currant, rose, vanilla, vetiver.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/carolina-herrera-very-good-girl-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/carolina-herrera-very-good-girl-edp_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
