INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('chanel-allure-homme-sport-eau-extreme-edp', 'Chanel', 'Allure Homme Sport Eau Extreme', 'EDP', 'men', 'aromatic', 2012, '{"top":["Mandarin Orange","Mint","Cypress","Sage"],"heart":["Pepper"],"base":["Tonka Bean","Musk","Sandalwood","Cedar"]}', 'Chanel Allure Homme Sport Eau Extreme: Эрэгтэйчүүдэд зориулсан өвслөг үнэр (EDP). Эхний ноот: мандарин, гаа, кипарис, мэргэн өвс; зүрхний ноот: хар чинжүү; суурь ноот: тонка шош, заар, зандан мод, хуш мод.', 'Chanel Allure Homme Sport Eau Extreme is a aromatic fragrance in EDP concentration. Its listed notes include mandarin, mint, cypress, sage, black pepper.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/chanel-allure-homme-sport-eau-extreme-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/chanel-allure-homme-sport-eau-extreme-edp_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('chanel-allure-homme-sport-edt', 'Chanel', 'Allure Homme Sport', 'EDT', 'men', 'citrus', NULL, '{"top":["Orange","Marine notes","Aldehydes","Mandarin"],"heart":["Black pepper","Neroli","Cedar"],"base":["Vanilla","Tonka bean","Musk","Amber","Vetiver"]}', 'Chanel брэндийн Allure Homme Sport нь эрэгтэй хүмүүст зориулагдсан Амлагчит Модлог ангилалын сүрчиг юм.', 'Chanel Allure Homme Sport is a citrus EDT for men. Notes include orange, marine notes, aldehydes, mandarin, black pepper, neroli.', '/product-photos/store/chanel-allure-homme-sport-edt.webp', NULL, 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('chanel-bleu-de-chanel-edp', 'Chanel', 'Bleu de Chanel', 'EDP', 'men', 'citrus', 2014, '{"top":["Grapefruit","Lemon","Mint","Pink Pepper","Bergamot","Aldehydes","Coriander"],"heart":["Ginger","Nutmeg","Jasmine","Melon"],"base":["Incense","Amber","Cedar","Sandalwood","Patchouli","Amberwood","Labdanum"]}', 'Chanel Bleu de Chanel: Эрэгтэйчүүдэд зориулсан цитрус үнэр (EDP). Эхний ноот: бэрсүүт жүрж, нимбэг, гаа, ягаан чинжүү, бергамот, альдегид, кориандр; зүрхний ноот: цагаан гаа, задийн самар, жасмин, амтат гуа; суурь ноот: хүж, хув, хуш мод, зандан мод, пачули, хув мод, лабданум.', 'Chanel Bleu de Chanel is a citrus fragrance in EDP concentration. Its listed notes include grapefruit, lemon, mint, pink pepper, bergamot.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/chanel-bleu-de-chanel-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/chanel-bleu-de-chanel-edp_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('chanel-bleu-de-chanel-parfum', 'Chanel', 'Bleu de Chanel', 'Parfum', 'men', 'woody', 2018, '{"top":["Lemon Zest","Bergamot","Mint","Artemisia"],"heart":["Lavender","Pineapple","Geranium","Green Notes"],"base":["Sandalwood","Cedar","Amberwood","Iso E Super","Tonka Bean"]}', 'Chanel Bleu de Chanel: Эрэгтэйчүүдэд зориулсан модлог үнэр (Parfum). Эхний ноот: нимбэгийн хальс, бергамот, гаа, шарилж; зүрхний ноот: лаванда, хан боргоцой, герань, ногоон ноот; суурь ноот: зандан мод, хуш мод, хув мод, iso e super, тонка шош.', 'Chanel Bleu de Chanel is a woody fragrance in Parfum concentration. Its listed notes include lemon zest, bergamot, mint, artemisia, lavender.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/chanel-bleu-de-chanel-parfum_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/chanel-bleu-de-chanel-parfum_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('chanel-chance-eau-tendre-edp', 'Chanel', 'Chance Eau Tendre', 'EDP', 'women', 'floral', NULL, '{"top":["Quince","Grapefruit"],"heart":["Rose","Jasmine"],"base":["White Musk"]}', 'Chanel Chance Eau Tendre: Эмэгтэйчүүдэд зориулсан цэцэгсийн үнэр (EDP). Эхний ноот: айва, бэрсүүт жүрж; зүрхний ноот: сарнай, жасмин; суурь ноот: заар.', 'Chanel Chance Eau Tendre is a floral fragrance in EDP concentration. Its listed notes include quince, grapefruit, rose, jasmine, musk.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/chanel-chance-eau-tendre-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/chanel-chance-eau-tendre-edp_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('chanel-coco-mademoiselle-edp', 'Chanel', 'Coco Mademoiselle', 'EDP', 'women', 'citrus', 2001, '{"top":["Orange","Mandarin Orange","Bergamot","Orange Blossom"],"heart":["Turkish Rose","Jasmine","Mimosa","Ylang-Ylang"],"base":["Patchouli","White Musk","Vanilla","Vetiver","Tonka Bean","Opoponax"]}', 'Chanel Coco Mademoiselle: Эмэгтэйчүүдэд зориулсан цитрус үнэр (EDP). Эхний ноот: жүрж, мандарин, бергамот, жүржийн цэцэг; зүрхний ноот: сарнай, жасмин, мимоза, иланг-иланг; суурь ноот: пачули, заар, ваниль, ветивер, тонка шош, опопонакс.', 'Chanel Coco Mademoiselle is a citrus fragrance in EDP concentration. Its listed notes include orange, mandarin, bergamot, orange blossom, rose.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/chanel-coco-mademoiselle-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/chanel-coco-mademoiselle-edp_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
