INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('dior-homme-intense-edp', 'Dior', 'Homme Intense', 'EDP', 'men', 'woody', NULL, '{"top":["Lavender"],"heart":["Iris","Ambrette","Pear"],"base":["Cedar","Vetiver"]}', 'Dior Homme Intense: Эрэгтэйчүүдэд зориулсан модлог үнэр (EDP). Эхний ноот: лаванда; зүрхний ноот: цахилдаг, амбретт, лийр; суурь ноот: хуш мод, ветивер.', 'Dior Homme Intense is a woody fragrance in EDP concentration. Its listed notes include lavender, iris, ambrette, pear, cedar.', '/product-photos/curated-008-front.webp', '/product-photos/curated-008-back.webp', 'active', 'content') ON CONFLICT(id) DO NOTHING;
