INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('dior-hypnotic-poison-edt', 'Dior', 'Hypnotic Poison', 'EDT', 'women', 'gourmand', 1998, '{"top":["Coconut","Plum","Apricot"],"heart":["Brazilian Rosewood","Jasmine","Caraway","Tuberose","Rose","Lily-Of-The-Valley"],"base":["Vanilla","Almond","Sandalwood","Musk"]}', 'Dior Hypnotic Poison: Эмэгтэйчүүдэд зориулсан гурман үнэр (EDT). Эхний ноот: кокос, чавга, чангаанз; зүрхний ноот: сарнай мод, жасмин, гоньд, тубероз, сарнай, хонхон цэцэг; суурь ноот: ваниль, бүйлс, зандан мод, заар.', 'Dior Hypnotic Poison is a gourmand fragrance in EDT concentration. Its listed notes include coconut, plum, apricot, rosewood, jasmine.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/dior-hypnotic-poison-edt_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/dior-hypnotic-poison-edt_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
