INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('dior-jadore-edp', 'Dior', 'J''adore', 'EDP', 'women', 'floral', NULL, '{"top":["Peach","Magnolia","Mandarin","Pear","Bergamot","Melon"],"heart":["Rose","Violet","Freesia","Plum","Jasmine","Orchid","Tuberose"],"base":["Cedar","blackberry","Musk","Vanilla"]}', 'Dior J''adore: Эмэгтэйчүүдэд зориулсан цэцэгсийн үнэр (EDP). Эхний ноот: тоор, магнолия, мандарин, лийр, бергамот, амтат гуа; зүрхний ноот: сарнай, нил цэцэг, фрезия, чавга, жасмин, цахирмаа, тубероз; суурь ноот: хуш мод, хар бөөрөлзгөнө, заар, ваниль.', 'Dior J''adore is a floral fragrance in EDP concentration. Its listed notes include peach, magnolia, mandarin, pear, bergamot.', '/product-photos/curated-058-front.webp', '/product-photos/curated-058-back.webp', 'active', 'content') ON CONFLICT(id) DO NOTHING;
