INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('dolce-and-gabbana-light-blue-eau-intense-edp', 'Dolce&Gabbana', 'Light Blue Eau Intense', 'EDP', 'men', 'woody', NULL, '{"top":["Grapefruit","Mandarin"],"heart":["Marine notes","Juniper"],"base":["Musk","Amberwood"]}', 'Dolce&Gabbana Light Blue Eau Intense: Эрэгтэйчүүдэд зориулсан модлог үнэр (EDP). Эхний ноот: бэрсүүт жүрж, мандарин; зүрхний ноот: далайн ноот, арц; суурь ноот: заар, хув мод.', 'Dolce&Gabbana Light Blue Eau Intense is a woody fragrance in EDP concentration. Its listed notes include grapefruit, mandarin, marine notes, juniper, musk.', '/product-photos/curated-036-front.webp', '/product-photos/curated-036-back.webp', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('dolce-and-gabbana-the-one-edp', 'Dolce&Gabbana', 'The One', 'EDP', 'men', 'citrus', NULL, '{"top":["Grapefruit","Coriander","Basil"],"heart":["Cardamom","Ginger","Orange blossom"],"base":["Amber","Tobacco leaf","Cedar"]}', 'Dolce&Gabbana The One: Эрэгтэйчүүдэд зориулсан цитрус үнэр (EDP). Эхний ноот: бэрсүүт жүрж, кориандр, базилик; зүрхний ноот: кардамон, цагаан гаа, жүржийн цэцэг; суурь ноот: хув, тамхины навч, хуш мод.', 'Dolce&Gabbana The One is a citrus fragrance in EDP concentration. Its listed notes include grapefruit, coriander, basil, cardamom, ginger.', '/product-photos/curated-035-front.webp', NULL, 'active', 'content') ON CONFLICT(id) DO NOTHING;
