INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('emporio-armani-stronger-with-you-absolutely-parfum', 'Emporio Armani', 'Stronger With You Absolutely', 'Parfum', 'men', 'amber', NULL, '{"top":["Rum","Elemi","Bergamot"],"heart":["Lavender","Davana"],"base":["Chestnut","Vanilla","Cedar","Patchouli"]}', 'Emporio Armani Stronger With You Absolutely: Эрэгтэйчүүдэд зориулсан хув үнэр (Parfum). Эхний ноот: ром, элеми давирхай, бергамот; зүрхний ноот: лаванда, давана; суурь ноот: туулайн бөөр, ваниль, хуш мод, пачули.', 'Emporio Armani Stronger With You Absolutely is a amber fragrance in Parfum concentration. Its listed notes include rum, elemi, bergamot, lavender, davana.', '/product-photos/curated-017-front.webp', '/product-photos/curated-017-back.webp', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('emporio-armani-stronger-with-you-intensely-edp', 'Emporio Armani', 'Stronger With You Intensely', 'EDP', 'men', 'amber', NULL, '{"top":["Pink pepper","Juniper","Violet"],"heart":["Toffee","Cinnamon","Lavender","Sage"],"base":["Vanilla","Tonka bean","Amber","Suede"]}', 'Emporio Armani Stronger With You Intensely: Эрэгтэйчүүдэд зориулсан хув үнэр (EDP). Эхний ноот: ягаан чинжүү, арц, нил цэцэг; зүрхний ноот: ирис чихэр, шанцай, лаванда, мэргэн өвс; суурь ноот: ваниль, тонка шош, хув, илгэ.', 'Emporio Armani Stronger With You Intensely is a amber fragrance in EDP concentration. Its listed notes include pink pepper, juniper, violet, toffee, cinnamon.', '/product-photos/store/emporio-armani-stronger-with-you-intensely-edp.webp', '/product-photos/curated-016-back.webp', 'active', 'content') ON CONFLICT(id) DO NOTHING;
