INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('lancome-la-vie-est-belle-edp', 'Lancôme', 'La Vie Est Belle', 'EDP', 'women', 'floral', 2012, '{"top":["Black Currant","Pear"],"heart":["Iris","Jasmine","Orange Blossom"],"base":["Praline","Vanilla","Patchouli","Tonka Bean"]}', 'Lancôme La Vie Est Belle: Эмэгтэйчүүдэд зориулсан цэцэгсийн үнэр (EDP). Эхний ноот: үхрийн нүд, лийр; зүрхний ноот: цахилдаг, жасмин, жүржийн цэцэг; суурь ноот: пралине, ваниль, пачули, тонка шош.', 'Lancôme La Vie Est Belle is a floral fragrance in EDP concentration. Its listed notes include blackcurrant, pear, iris, jasmine, orange blossom.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/lancome-la-vie-est-belle-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/lancome-la-vie-est-belle-edp_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
