INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('lattafa-asad-edp', 'Lattafa', 'Asad', 'EDP', 'men', 'amber', 2021, '{"top":["Black Pepper","Tobacco","Pineapple"],"heart":["Patchouli","Coffee","Iris"],"base":["Vanilla","Amber","Dry Wood","Benzoin","Labdanum"]}', 'Lattafa Asad: Эрэгтэйчүүдэд зориулсан хув үнэр (EDP). Эхний ноот: хар чинжүү, тамхины навч, хан боргоцой; зүрхний ноот: пачули, кофе, цахилдаг; суурь ноот: ваниль, хув, модлог ноот, бензойн, лабданум.', 'Lattafa Asad is a amber fragrance in EDP concentration. Its listed notes include black pepper, tobacco leaf, pineapple, patchouli, coffee.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/lattafa-asad-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/lattafa-asad-edp_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
