INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('lattafa-badee-al-oud-honor-and-glory-edp', 'Lattafa', 'Bade''e Al Oud Honor & Glory', 'EDP', 'unisex', 'gourmand', NULL, '{"top":["Pineapple","Creme Brulee"],"heart":["Cinnamon","Turmeric","Benzoin","Black pepper"],"base":["Vanilla","Sandalwood","cashmeran","Moss"]}', 'Lattafa Bade''e Al Oud Honor & Glory: Unisex гурман үнэр (EDP). Эхний ноот: хан боргоцой, крем брюле; зүрхний ноот: шанцай, куркума, бензойн, хар чинжүү; суурь ноот: ваниль, зандан мод, кашмеран, хөвд.', 'Lattafa Bade''e Al Oud Honor & Glory is a gourmand fragrance in EDP concentration. Its listed notes include pineapple, creme brulee, cinnamon, turmeric, benzoin.', '/product-photos/curated-096-front.webp', NULL, 'active', 'content') ON CONFLICT(id) DO NOTHING;
