INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('lattafa-khamrah-edp', 'Lattafa', 'Khamrah', 'EDP', 'unisex', 'gourmand', 2022, '{"top":["Cinnamon","Nutmeg","Bergamot"],"heart":["Dates","Praline","Tuberose","Mahonial"],"base":["Vanilla","Tonka Bean","Amberwood","Myrrh","Benzoin","Akigalawood"]}', 'Lattafa Khamrah: Unisex гурман үнэр (EDP). Эхний ноот: шанцай, задийн самар, бергамот; зүрхний ноот: хасарваань, пралине, тубероз, махониал; суурь ноот: ваниль, тонка шош, хув мод, мирра, бензойн, акигалавүүд.', 'Lattafa Khamrah is a gourmand fragrance in EDP concentration. Its listed notes include cinnamon, nutmeg, bergamot, dates, praline.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/lattafa-khamrah-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/lattafa-khamrah-edp_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
