INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('prada-lhomme-edt', 'Prada', 'L''Homme', 'EDT', 'men', 'floral', NULL, '{"top":["Neroli","Black pepper","Cardamom","Carrot Seeds"],"heart":["Iris","Violet","Geranium","Mate"],"base":["Amber","Cedar","Sandalwood","Patchouli"]}', 'Prada L''Homme: Эрэгтэйчүүдэд зориулсан цэцэгсийн үнэр (EDT). Эхний ноот: нероли, хар чинжүү, кардамон, луувангийн үр; зүрхний ноот: цахилдаг, нил цэцэг, герань, мате цай; суурь ноот: хув, хуш мод, зандан мод, пачули.', 'Prada L''Homme is a floral fragrance in EDT concentration. Its listed notes include neroli, black pepper, cardamom, carrot seeds, iris.', '/product-photos/curated-034-front.webp', NULL, 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('prada-luna-rossa-black-edp', 'Prada', 'Luna Rossa Black', 'EDP', 'men', 'amber', 2018, '{"top":["Bergamot"],"heart":["Angelica","Patchouli"],"base":["Coumarin","Amber","Musk"]}', 'Prada Luna Rossa Black: Эрэгтэйчүүдэд зориулсан хув үнэр (EDP). Эхний ноот: бергамот; зүрхний ноот: анжелика, пачули; суурь ноот: кумарин, хув, заар.', 'Prada Luna Rossa Black is a amber fragrance in EDP concentration. Its listed notes include bergamot, angelica, patchouli, coumarin, amber.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/prada-luna-rossa-black-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/prada-luna-rossa-black-edp_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('prada-luna-rossa-carbon-edt', 'Prada', 'Luna Rossa Carbon', 'EDT', 'men', 'aromatic', 2017, '{"top":["Bergamot","Pepper"],"heart":["Lavender","Metallic Notes","Coal","Watery Notes","Soil Tincture"],"base":["Ambroxan","Patchouli"]}', 'Prada Luna Rossa Carbon: Эрэгтэйчүүдэд зориулсан өвслөг үнэр (EDT). Эхний ноот: бергамот, хар чинжүү; зүрхний ноот: лаванда, металллаг ноот, нүүрс, далайн ноот, хөрсний ханд; суурь ноот: амброксан, пачули.', 'Prada Luna Rossa Carbon is a aromatic fragrance in EDT concentration. Its listed notes include bergamot, black pepper, lavender, metallic notes, coal.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/prada-luna-rossa-carbon-edt_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/prada-luna-rossa-carbon-edt_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
