INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('prada-paradoxe-edp', 'Prada', 'Paradoxe', 'EDP', 'women', 'floral', 2022, '{"top":["Pear","Tangerine","Bergamot"],"heart":["Orange Blossom","Neroli Essence","Neroli","Jasmine Sambac"],"base":["Bourbon Vanilla","Amber","White Musk","Benzoin"]}', 'Prada Paradoxe: Эмэгтэйчүүдэд зориулсан цэцэгсийн үнэр (EDP). Эхний ноот: лийр, мандарин, бергамот; зүрхний ноот: жүржийн цэцэг, нероли, жасмин; суурь ноот: ваниль, хув, заар, бензойн.', 'Prada Paradoxe is a floral fragrance in EDP concentration. Its listed notes include pear, mandarin, bergamot, orange blossom, neroli.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/prada-paradoxe-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/prada-paradoxe-edp_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('prada-paradoxe-intense-edp', 'Prada', 'Paradoxe Intense', 'EDP', 'women', 'floral', 2023, '{"top":["Pear","Neroli","Bergamot"],"heart":["Moss","Jasmine","Neroli Essence"],"base":["Bourbon Vanilla","Vanilla","Amber","Ambrofix™","Serenolide"]}', 'Prada Paradoxe Intense: Эмэгтэйчүүдэд зориулсан цэцэгсийн үнэр (EDP). Эхний ноот: лийр, нероли, бергамот; зүрхний ноот: хөвд, жасмин, нероли; суурь ноот: ваниль, хув, амброфикс, серенолид.', 'Prada Paradoxe Intense is a floral fragrance in EDP concentration. Its listed notes include pear, neroli, bergamot, moss, jasmine.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/prada-paradoxe-intense-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/prada-paradoxe-intense-edp_back.png', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('r-my-latour-cigar-edt', 'Rémy Latour', 'Cigar', 'EDT', 'men', 'woody', NULL, '{"top":["Bergamot","Lemon","Pear","Pineapple","Plum"],"heart":["African Marigold","Geranium","Jasmine","Laurel","Basil","Nutmeg"],"base":["Tobacco leaf","Sandalwood","Cedar","Patchouli","Musk"]}', 'Францын алдартай Rémy Latour брэндийн "Cigar" Eau de Toilette (EDT) нь эрчүүдэд зориулсан сонгодог, хүчирхэг, модлог ба тамхины (tobacco) ноот голлосон алдартай сүрчиг юм. 90-ээд оны үеийн казино, дээд зэрэглэлийн клубүүдийн уур амьсгалыг санагдуулам эршүүд төрхийг илэрхийлдэг', 'Rémy Latour Cigar is a woody EDT for men. Notes include bergamot, lemon, pear, pineapple, plum, african marigold.', '/product-photos/store/r-my-latour-cigar-edt.webp', NULL, 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('rabanne-1-million-edt', 'Rabanne', '1 Million', 'EDT', 'men', 'citrus', NULL, '{"top":["Mandarin","Grapefruit","Mint"],"heart":["Cinnamon","Black pepper","Rose"],"base":["Amber","Leather","Woods","Patchouli"]}', 'Rabanne 1 Million: Эрэгтэйчүүдэд зориулсан цитрус үнэр (EDT). Эхний ноот: мандарин, бэрсүүт жүрж, гаа; зүрхний ноот: шанцай, хар чинжүү, сарнай; суурь ноот: хув, арьс, модлог ноот, пачули.', 'Rabanne 1 Million is a citrus fragrance in EDT concentration. Its listed notes include mandarin, grapefruit, mint, cinnamon, black pepper.', '/product-photos/curated-027-front.webp', NULL, 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('rabanne-1-million-elixir-edp', 'Rabanne', '1 Million Elixir', 'EDP', 'men', 'woody', NULL, '{"top":["Apple","Davana"],"heart":["Osmanthus","Rose","Cedar"],"base":["Vanilla","Tonka bean","Patchouli"]}', 'Rabanne 1 Million Elixir: Эрэгтэйчүүдэд зориулсан модлог үнэр (EDP). Эхний ноот: алим, давана; зүрхний ноот: османтус, сарнай, хуш мод; суурь ноот: ваниль, тонка шош, пачули.', 'Rabanne 1 Million Elixir is a woody fragrance in EDP concentration. Its listed notes include apple, davana, osmanthus, rose, cedar.', '/product-photos/curated-028-front.webp', '/product-photos/curated-028-back.webp', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('rabanne-invictus-victory-elixir-parfum', 'Rabanne', 'Invictus Victory Elixir', 'Parfum', 'men', 'gourmand', NULL, '{"top":["Lavender","Cardamom","Black pepper"],"heart":["Incense","Patchouli"],"base":["Vanilla","Tonka bean"]}', 'Rabanne Invictus Victory Elixir: Эрэгтэйчүүдэд зориулсан гурман үнэр (Parfum). Эхний ноот: лаванда, кардамон, хар чинжүү; зүрхний ноот: хүж, пачули; суурь ноот: ваниль, тонка шош.', 'Rabanne Invictus Victory Elixir is a gourmand fragrance in Parfum concentration. Its listed notes include lavender, cardamom, black pepper, incense, patchouli.', '/product-photos/curated-029-front.webp', '/product-photos/curated-029-back.webp', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('rabanne-phantom-parfum', 'Rabanne', 'Phantom', 'Parfum', 'men', 'aromatic', NULL, '{"top":["Cardamom","Bergamot","Rhubarb","Lemon"],"heart":["Lavender","Patchouli","Cedar","Geranium"],"base":["Vanilla","tolu balsam","Vetiver"]}', 'Rabanne Phantom: Эрэгтэйчүүдэд зориулсан өвслөг үнэр (Parfum). Эхний ноот: кардамон, бергамот, гишүүнэ, нимбэг; зүрхний ноот: лаванда, пачули, хуш мод, герань; суурь ноот: ваниль, толу бальзам, ветивер.', 'Rabanne Phantom is a aromatic fragrance in Parfum concentration. Its listed notes include cardamom, bergamot, rhubarb, lemon, lavender.', '/product-photos/curated-030-front.webp', '/product-photos/curated-030-back.webp', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('ralph-lauren-polo-black-edt', 'Ralph Lauren', 'Polo Black', 'EDT', 'men', 'woody', NULL, '{"top":["Sandalwood"],"heart":["Patchouli","Tonka bean","Sage"],"base":["Lemon","Artemisia"]}', 'Ralph Lauren брэндийн Polo Black нь эрэгтэй хүмүүст зориулагдсан Анхилуун Модлог ангилалын сүрчиг юм', 'Ralph Lauren Polo Black is a woody EDT for men. Notes include sandalwood, patchouli, tonka bean, sage, lemon, artemisia.', '/product-photos/store/ralph-lauren-polo-black-edt.webp', NULL, 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('ralph-lauren-polo-blue-edp', 'Ralph Lauren', 'Polo Blue', 'EDP', NULL, NULL, NULL, '{"top":["Sea Notes","Bergamot","Cardamom"],"heart":["Basil","Verbena","Clary Sage","Orris"],"base":["Suede","Woodsy Notes","Vetiver","Patchouli"]}', NULL, NULL, 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/ralph-lauren-polo-blue-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/ralph-lauren-polo-blue-edp_back.jpg', 'draft', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
