INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('valentino-donna-born-in-roma-edp', 'Valentino', 'Donna Born In Roma', 'EDP', 'women', 'floral', 2019, '{"top":["Black Currant","Pink Pepper","Bergamot"],"heart":["Jasmine","Jasmine Sambac","Jasmine Tea"],"base":["Bourbon Vanilla","Cashmeran","Guaiac Wood"]}', 'Valentino Donna Born in Roma: Эмэгтэйчүүдэд зориулсан цэцэгсийн үнэр (EDP). Эхний ноот: үхрийн нүд, ягаан чинжүү, бергамот; зүрхний ноот: жасмин, ногоон цай; суурь ноот: ваниль, кашмеран, гваяк мод.', 'Valentino Donna Born in Roma is a floral fragrance in EDP concentration. Its listed notes include blackcurrant, pink pepper, bergamot, jasmine, green tea.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/valentino-donna-born-in-roma-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/valentino-donna-born-in-roma-edp_back.png', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
