INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('valentino-uomo-born-in-roma-edt', 'Valentino', 'Uomo Born in Roma', 'EDT', 'men', 'woody', 2019, '{"top":["Mineral Notes","Violet Leaf","Salt"],"heart":["Ginger","Sage"],"base":["Woody Notes","Vetiver"]}', 'Valentino Uomo Born in Roma: Эрэгтэйчүүдэд зориулсан модлог үнэр (EDT). Эхний ноот: эрдсийн ноот, нил цэцгийн навч, далайн давс; зүрхний ноот: цагаан гаа, мэргэн өвс; суурь ноот: модлог ноот, ветивер.', 'Valentino Uomo Born in Roma is a woody fragrance in EDT concentration. Its listed notes include mineral notes, violet leaf, sea salt, ginger, sage.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/valentino-uomo-born-in-roma-edt_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/valentino-uomo-born-in-roma-edt_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
