INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('versace-bright-crystal-edt', 'Versace', 'Bright Crystal', 'EDT', 'women', 'floral', NULL, '{"top":["Yuzu","pomegranate","ice"],"heart":["Peony","Lotus","Magnolia"],"base":["Musk","mahogany","Amber"]}', 'Versace Bright Crystal: Эмэгтэйчүүдэд зориулсан цэцэгсийн үнэр (EDT). Эхний ноот: юзу, анар, мөс; зүрхний ноот: цээнэ цэцэг, бадамлянхуа, магнолия; суурь ноот: заар, зандан мод, хув.', 'Versace Bright Crystal is a floral fragrance in EDT concentration. Its listed notes include yuzu, pomegranate, ice, peony, lotus.', '/product-photos/curated-066-front.webp', '/product-photos/curated-066-back.webp', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('versace-crystal-noir-edp', 'Versace', 'Crystal Noir', 'EDP', 'women', 'gourmand', 2004, '{"top":["Pepper","Ginger","Cardamom"],"heart":["Coconut","Gardenia","Orange Blossom","Peony"],"base":["Sandalwood","Musk","Amber"]}', 'Versace Crystal Noir: Эмэгтэйчүүдэд зориулсан гурман үнэр (EDP). Эхний ноот: хар чинжүү, цагаан гаа, кардамон; зүрхний ноот: кокос, гардения, жүржийн цэцэг, цээнэ цэцэг; суурь ноот: зандан мод, заар, хув.', 'Versace Crystal Noir is a gourmand fragrance in EDP concentration. Its listed notes include black pepper, ginger, cardamom, coconut, gardenia.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/versace-crystal-noir-edp_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/versace-crystal-noir-edp_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
