INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('versace-dylan-blue-edt', 'Versace', 'Dylan Blue', 'EDT', 'men', 'citrus', 2016, '{"top":["Bergamot","Grapefruit","Fig","Aquatic Accord"],"heart":["Violet Leaf","Pepper","Papyrus","Ambroxan","Patchouli"],"base":["Musk","Tonka Bean","Saffron","Incense"]}', 'Versace Dylan Blue: Эрэгтэйчүүдэд зориулсан цитрус үнэр (EDT). Эхний ноот: бергамот, бэрсүүт жүрж, инжир, далайн ноот; зүрхний ноот: нил цэцгийн навч, хар чинжүү, папирус, амброксан, пачули; суурь ноот: заар, тонка шош, гүргэм, хүж.', 'Versace Dylan Blue is a citrus fragrance in EDT concentration. Its listed notes include bergamot, grapefruit, fig, marine notes, violet leaf.', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/versace-dylan-blue-edt_front.jpg', 'https://pub-83d529150bc84a489ddcb74b42624830.r2.dev/versace-dylan-blue-edt_back.jpg', 'active', 'r2-catalog') ON CONFLICT(id) DO NOTHING;
