INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('versace-eros-edt', 'Versace', 'Eros', 'EDT', 'men', 'woody', NULL, '{"top":["Mint","Green apple","Lemon"],"heart":["Tonka bean","Ambroxan","Geranium"],"base":["Vanilla","Cedar","Vetiver","Oakmoss"]}', 'Versace Eros: Эрэгтэйчүүдэд зориулсан модлог үнэр (EDT). Эхний ноот: гаа, ногоон алим, нимбэг; зүрхний ноот: тонка шош, амброксан, герань; суурь ноот: ваниль, хуш мод, ветивер, царсны хөвд.', 'Versace Eros is a woody fragrance in EDT concentration. Its listed notes include mint, green apple, lemon, tonka bean, ambroxan.', '/product-photos/curated-023-front.webp', '/product-photos/curated-023-back.webp', 'active', 'content') ON CONFLICT(id) DO NOTHING;
