INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('victorias-secret-bombshell-edp', 'Victoria''s Secret', 'Bombshell', 'EDP', 'women', 'fresh', NULL, '{"top":["Passionfruit","Grapefruit","Pineapple","Mandarin","strawberry"],"heart":["Peony","vanilla orchid","red berries","Jasmine","Lily-of-the-valley"],"base":["Musk","Woods","Oakmoss"]}', 'Victoria''s Secret Bombshell: Эмэгтэйчүүдэд зориулсан сэрүүн үнэр (EDP). Эхний ноот: маракуйя, бэрсүүт жүрж, хан боргоцой, мандарин, гүзээлзгэнэ; зүрхний ноот: цээнэ цэцэг, ванилийн цахирмаа, улаан жимсгэнэ, жасмин, хонхон цэцэг; суурь ноот: заар, модлог ноот, царсны хөвд.', 'Victoria''s Secret Bombshell is a fresh fragrance in EDP concentration. Its listed notes include passionfruit, grapefruit, pineapple, mandarin, strawberry.', '/product-photos/curated-108-front.webp', NULL, 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('viktor-and-rolf-flowerbomb-edp', 'Viktor&Rolf', 'Flowerbomb', 'EDP', 'women', 'amber', NULL, '{"top":["Green tea","Bergamot","Osmanthus"],"heart":["Orchid","Jasmine","Rose","Freesia","Orange blossom"],"base":["Patchouli","Musk","Vanilla"]}', 'Viktor&Rolf Flowerbomb: Эмэгтэйчүүдэд зориулсан хув үнэр (EDP). Эхний ноот: ногоон цай, бергамот, османтус; зүрхний ноот: цахирмаа, жасмин, сарнай, фрезия, жүржийн цэцэг; суурь ноот: пачули, заар, ваниль.', 'Viktor&Rolf Flowerbomb is a amber fragrance in EDP concentration. Its listed notes include green tea, bergamot, osmanthus, orchid, jasmine.', '/product-photos/curated-062-front.webp', '/product-photos/curated-062-back.webp', 'active', 'content') ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id, brand, name, concentration, gender, family, release_year, notes_json, description_mn, description_en, image_front, image_back, status, source) VALUES ('viktor-and-rolf-spicebomb-extreme-edp', 'Viktor&Rolf', 'Spicebomb Extreme', 'EDP', 'men', 'amber', NULL, '{"top":["Black pepper","Pimento","Grapefruit"],"heart":["Cinnamon","Cumin","Saffron"],"base":["Vanilla","Tobacco leaf","Amber","Cistus"]}', 'Viktor&Rolf Spicebomb Extreme: Эрэгтэйчүүдэд зориулсан хув үнэр (EDP). Эхний ноот: хар чинжүү, пимент, бэрсүүт жүрж; зүрхний ноот: шанцай, зира, гүргэм; суурь ноот: ваниль, тамхины навч, хув, ладан бут.', 'Viktor&Rolf Spicebomb Extreme is a amber fragrance in EDP concentration. Its listed notes include black pepper, pimento, grapefruit, cinnamon, cumin.', '/product-photos/curated-031-front.webp', '/product-photos/curated-031-back.webp', 'active', 'content') ON CONFLICT(id) DO NOTHING;
